const protect = async (req, res, next) => {
  try {
    let token;

    if (
      req.headers.authorization &&
      req.headers.authorization.startsWith('Bearer')
    ) {
      token = req.headers.authorization.split(' ')[1];
    } else if (req.cookies.jwt) {
      token = req.cookies.jwt;
    }

    if (!token) {
      return res.status(401).json({
        status: 'fail',
        message: 'You are not logged in! Please log in to get access.'
      });
    }

    const decoded = verifyJWT(token);

    const currentUser = await User.findById(decoded.id).select(
      '+passwordChangedAt +twoFactorAuth.secret'
    );

    if (!currentUser) {
      return res.status(401).json({
        status: 'fail',
        message: 'The user belonging to this token no longer exists.'
      });
    }

    if (
      currentUser.passwordChangedAt &&
      decoded.iat < currentUser.passwordChangedAt.getTime() / 1000
    ) {
      return res.status(401).json({
        status: 'fail',
        message: 'User recently changed password! Please log in again.'
      });
    }

    if (currentUser.status !== 'active') {
      return res.status(401).json({
        status: 'fail',
        message: 'Your account has been suspended. Please contact support.'
      });
    }

    /*
     * 2FA protection
     *
     * IMPORTANT:
     * /api/convert is intentionally NOT included here.
     *
     * Conversion still requires a valid JWT because this middleware
     * protects the route, but it does not require the x-2fa-verified
     * header. This prevents a normal conversion request from being
     * incorrectly returned as:
     *
     * 401 { requires2FA: true }
     *
     * which the frontend could interpret as a session expiration.
     */
    if (currentUser.twoFactorAuth?.enabled) {
      const sensitiveRoutes = [
        '/api/withdrawals',
        '/api/withdrawals/spot',
        '/api/withdrawals/bank',
        '/api/withdrawals/btc',
        '/api/transactions/transfer',
        '/api/admin',
        '/api/payments',
        '/api/loans/apply',
        '/api/loans/repay'
      ];

      const requires2FA = sensitiveRoutes.some((route) =>
        req.path.startsWith(route)
      );

      if (requires2FA && !req.headers['x-2fa-verified']) {
        return res.status(401).json({
          status: 'fail',
          message: 'Two-factor authentication required',
          requires2FA: true
        });
      }
    }

    req.user = currentUser;
    next();
  } catch (err) {
    return res.status(401).json({
      status: 'fail',
      message: err.message || 'Invalid token. Please log in again.'
    });
  }
};







const adminProtect = async (req, res, next) => {
  try {
    let token;
    if (req.headers.authorization && req.headers.authorization.startsWith('Bearer')) {
      token = req.headers.authorization.split(' ')[1];
    } else if (req.cookies.admin_jwt) {
      token = req.cookies.admin_jwt;
    }

    if (!token) {
      return res.status(401).json({
        status: 'fail',
        message: 'You are not logged in! Please log in to get access.'
      });
    }

    const decoded = verifyJWT(token);
    if (!decoded.isAdmin) {
      return res.status(403).json({
        status: 'fail',
        message: 'You do not have permission to access this resource'
      });
    }

    const currentAdmin = await Admin.findById(decoded.id).select('+passwordChangedAt +twoFactorAuth.secret');
    if (!currentAdmin) {
      return res.status(401).json({
        status: 'fail',
        message: 'The admin belonging to this token no longer exists.'
      });
    }

    if (currentAdmin.twoFactorAuth.enabled && !req.headers['x-2fa-verified']) {
      return res.status(401).json({
        status: 'fail',
        message: 'Two-factor authentication required'
      });
    }

    req.admin = currentAdmin;
    next();
  } catch (err) {
    return res.status(401).json({
      status: 'fail',
      message: err.message || 'Invalid token. Please log in again.'
    });
  }
};

const restrictTo = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.admin.role)) {
      return res.status(403).json({
        status: 'fail',
        message: 'You do not have permission to perform this action'
      });
    }
    next();
  };
};

const checkCSRF = (req, res, next) => {
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    return next();
  }

  const csrfToken = req.headers['x-csrf-token'] || req.body._csrf;
  if (!csrfToken || !req.session.csrfToken || csrfToken !== req.session.csrfToken) {
    return res.status(403).json({
      status: 'fail',
      message: 'Invalid CSRF token'
    });
  }
  next();
};

const calculateReferralCommissions = async (investment) => {
  try {
    const populatedInvestment = await Investment.findById(investment._id)
      .populate('user', 'firstName lastName email')
      .populate('plan');

    if (!populatedInvestment) {
      console.log(`Investment not found: ${investment._id}`);
      return;
    }

    const investmentId = populatedInvestment._id;
    const investorId = populatedInvestment.user._id;
    const investmentAmount = populatedInvestment.amount;

    console.log(`Checking downline commissions for investment: ${investmentId}, user: ${investorId}, amount: $${investmentAmount}`);

    const relationship = await DownlineRelationship.findOne({
      downline: investorId,
      status: 'active',
      remainingRounds: { $gt: 0 }
    }).populate('upline', 'firstName lastName email balances referralStats downlineStats');

    if (!relationship) {
      console.log(`No active downline relationship found for user: ${investorId}`);
      return;
    }

    const uplineId = relationship.upline._id;
    const uplineUser = relationship.upline;
    const commissionPercentage = relationship.commissionPercentage;
    const commissionAmount = (investmentAmount * commissionPercentage) / 100;

    console.log(`Downline commission: $${investmentAmount} * ${commissionPercentage}% = $${commissionAmount} for upline: ${uplineUser.email}`);

    const commissionHistory = await CommissionHistory.create({
      upline: uplineId,
      downline: investorId,
      investment: investmentId,
      investmentAmount: investmentAmount,
      commissionPercentage: commissionPercentage,
      commissionAmount: commissionAmount,
      roundNumber: relationship.commissionRounds - relationship.remainingRounds + 1,
      status: 'paid',
      paidAt: new Date()
    });

    const updatedUpline = await User.findByIdAndUpdate(
      uplineId,
      {
        $inc: {
          'balances.main': commissionAmount,
          'referralStats.totalEarnings': commissionAmount,
          'referralStats.availableBalance': commissionAmount,
          'downlineStats.totalCommissionEarned': commissionAmount,
          'downlineStats.thisMonthCommission': commissionAmount
        }
      },
      { new: true }
    );

    console.log(`Updated upline ${uplineUser.email} MAIN balance with $${commissionAmount}. New balance: $${updatedUpline.balances.main}`);

    relationship.remainingRounds -= 1;
    relationship.totalCommissionEarned += commissionAmount;
    
    if (relationship.remainingRounds === 0) {
      relationship.status = 'completed';
      console.log(`Commission rounds completed for relationship: ${relationship._id}`);
    }

    await relationship.save();

    await Transaction.create({
      user: uplineId,
      type: 'referral',
      amount: commissionAmount,
      currency: 'USD',
      status: 'completed',
      method: 'INTERNAL',
      reference: `DOWNLINE-COMM-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      details: {
        commissionFrom: investorId,
        investmentId: investmentId,
        round: relationship.commissionRounds - relationship.remainingRounds + 1,
        totalRounds: relationship.commissionRounds,
        commissionType: 'downline',
        downlineName: `${populatedInvestment.user.firstName} ${populatedInvestment.user.lastName}`,
        percentage: commissionPercentage
      },
      fee: 0,
      netAmount: commissionAmount
    });

    await User.findByIdAndUpdate(uplineId, {
      $push: {
        referralHistory: {
          referredUser: investorId,
          amount: commissionAmount,
          percentage: commissionPercentage,
          level: 1,
          date: new Date(),
          status: 'available',
          type: 'downline_commission'
        }
      }
    });

    const activeDownlinesCount = await DownlineRelationship.countDocuments({ 
      upline: uplineId, 
      status: 'active',
      remainingRounds: { $gt: 0 }
    });

    await User.findByIdAndUpdate(uplineId, {
      'downlineStats.activeDownlines': activeDownlinesCount
    });

    console.log(`Downline commission of $${commissionAmount} paid to upline ${uplineUser.email} for investment ${investmentId} (Round ${relationship.commissionRounds - relationship.remainingRounds + 1}/${relationship.commissionRounds})`);

    await logActivity('downline_commission_paid', 'commission', commissionHistory._id, uplineId, 'User', null, {
      amount: commissionAmount,
      downline: investorId,
      investment: investmentId,
      round: relationship.commissionRounds - relationship.remainingRounds + 1,
      totalRounds: relationship.commissionRounds,
      percentage: commissionPercentage
    });

  } catch (err) {
    console.error('Downline commission calculation error:', err);
  }
};

const recalculateAllUserBalances = async (io) => {
  try {
    console.log('Recalculating ALL user balances based on current crypto prices...');
    
    const users = await User.find({}).select('_id balances');
    let updatedCount = 0;
    
    for (const user of users) {
      let totalMainValue = 0;
      let totalActiveValue = 0;
      let totalMaturedValue = 0;
      
      if (user.balances && user.balances.main) {
        const mainBalances = user.balances.main;
        const entries = mainBalances instanceof Map ? mainBalances.entries() : Object.entries(mainBalances);
        
        for (const [asset, balance] of entries) {
          if (balance > 0 && asset !== 'usd') {
            const price = await getCryptoPrice(asset.toUpperCase());
            if (price && price > 0) {
              totalMainValue += balance * price;
            }
          }
        }
      }
      
      if (user.balances && user.balances.active) {
        const activeBalances = user.balances.active;
        const entries = activeBalances instanceof Map ? activeBalances.entries() : Object.entries(activeBalances);
        
        for (const [asset, balance] of entries) {
          if (balance > 0) {
            if (asset === 'usd') {
              totalActiveValue += balance;
            } else {
              totalActiveValue += balance;
            }
          }
        }
      }
      
      if (user.balances && user.balances.matured) {
        const maturedBalances = user.balances.matured;
        const entries = maturedBalances instanceof Map ? maturedBalances.entries() : Object.entries(maturedBalances);
        
        for (const [asset, balance] of entries) {
          if (balance > 0 && asset !== 'usd') {
            const price = await getCryptoPrice(asset.toUpperCase());
            if (price && price > 0) {
              totalMaturedValue += balance * price;
            }
          }
        }
      }
      
      const currentMainUSD = user.balances?.main?.get?.('usd') || user.balances?.main?.usd || 0;
      const currentActiveUSD = user.balances?.active?.get?.('usd') || user.balances?.active?.usd || 0;
      const currentMaturedUSD = user.balances?.matured?.get?.('usd') || user.balances?.matured?.usd || 0;
      
      const needsMainUpdate = Math.abs(currentMainUSD - totalMainValue) > 0.01;
      const needsActiveUpdate = Math.abs(currentActiveUSD - totalActiveValue) > 0.01;
      const needsMaturedUpdate = Math.abs(currentMaturedUSD - totalMaturedValue) > 0.01;
      
      if (needsMainUpdate || needsActiveUpdate || needsMaturedUpdate) {
        if (!user.balances) user.balances = { main: new Map(), active: new Map(), matured: new Map() };
        if (!user.balances.main) user.balances.main = new Map();
        if (!user.balances.active) user.balances.active = new Map();
        if (!user.balances.matured) user.balances.matured = new Map();
        
        user.balances.main.set('usd', totalMainValue);
        user.balances.active.set('usd', totalActiveValue);
        user.balances.matured.set('usd', totalMaturedValue);
        
        await User.findByIdAndUpdate(user._id, { balances: user.balances });
        updatedCount++;
        
        if (io) {
          io.to(`user_${user._id}`).emit('balance_update', {
            main: totalMainValue,
            active: totalActiveValue,
            matured: totalMaturedValue
          });
          
          const previousDayKey = `user:${user._id}:prev_main_value`;
          const cachedPrev = await redis.get(previousDayKey);
          let dailyPnL = 0;
          let dailyPnLPercentage = 0;
          
          if (cachedPrev) {
            const prevValue = parseFloat(cachedPrev);
            dailyPnL = totalMainValue - prevValue;
            dailyPnLPercentage = prevValue > 0 ? (dailyPnL / prevValue) * 100 : 0;
          }
          
          io.to(`user_${user._id}`).emit('pnl_update', {
            main: {
              amount: dailyPnL,
              percentage: dailyPnLPercentage
            },
            matured: {
              amount: 0,
              percentage: 0
            }
          });
          
          const today = new Date().toDateString();
          const lastDate = await redis.get(`user:${user._id}:pnl_date`);
          if (lastDate !== today) {
            await redis.set(previousDayKey, totalMainValue);
            await redis.set(`user:${user._id}:pnl_date`, today);
          }
        }
      }
    }
    
    console.log(`Recalculated balances for ${updatedCount} users (Main: fluctuates, Active: fixed, Matured: fluctuates)`);
    
  } catch (err) {
    console.error('Error recalculating user balances:', err);
  }
};

const generateFinancialStatementsForAllUsers = async () => {
  console.log('🏦 [BANK CRON] Starting automatic financial statement generation...');
  const startTime = Date.now();
  
  try {
    const now = new Date();
    let periodStart, periodEnd;
    let statementType;
    
    const isLastDayOfMonth = now.getDate() === new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
    const isSunday = now.getDay() === 0;
    
    if (isLastDayOfMonth) {
      statementType = 'monthly';
      periodStart = new Date(now.getFullYear(), now.getMonth(), 1);
      periodStart.setHours(0, 0, 0, 0);
      periodEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0);
      periodEnd.setHours(23, 59, 59, 999);
      console.log(`📅 Generating MONTHLY statements for ${periodStart.toLocaleDateString()} to ${periodEnd.toLocaleDateString()}`);
    } else if (isSunday) {
      statementType = 'weekly';
      periodStart = new Date(now);
      periodStart.setDate(now.getDate() - 7);
      periodStart.setHours(0, 0, 0, 0);
      periodEnd = new Date(now);
      periodEnd.setHours(23, 59, 59, 999);
      console.log(`📅 Generating WEEKLY statements for ${periodStart.toLocaleDateString()} to ${periodEnd.toLocaleDateString()}`);
    } else {
      console.log('⏭️ Not a statement generation day. Skipping cron job.');
      return;
    }
    
    const users = await User.find({ status: 'active' }).select('_id firstName lastName email balances');
    console.log(`📊 Found ${users.length} active users to generate statements for`);
    
    let generatedCount = 0;
    let failedCount = 0;
    
    for (const user of users) {
      try {
        const existingStatement = await FinancialStatement.findOne({
          user: user._id,
          statementType: statementType,
          'period.startDate': periodStart,
          'period.endDate': periodEnd
        });
        
        if (existingStatement && existingStatement.isDelivered) {
          console.log(`⏭️ Statement already exists for user ${user.email}. Skipping.`);
          continue;
        }
        
        const transactions = await Transaction.find({
          user: user._id,
          createdAt: { $gte: periodStart, $lte: periodEnd },
          status: 'completed'
        }).sort({ createdAt: -1 });
        
        
        const previousTransactions = await Transaction.find({
          user: user._id,
          createdAt: { $lt: periodStart },
          status: 'completed'
        });
        
        let openingMainUSD = 0;
        let openingMaturedUSD = 0;
        let openingActiveUSD = 0;
        
        for (const tx of previousTransactions) {
          if (tx.type === 'deposit') {
            if (tx.method === 'btc' || tx.method === 'crypto') {
              openingMainUSD += tx.netAmount || tx.amount || 0;
            }
          } else if (tx.type === 'withdrawal') {
            if (tx.method === 'btc' || tx.method === 'crypto') {
              openingMainUSD -= tx.amount || 0;
            }
          } else if (tx.type === 'investment') {
            if (tx.details?.walletType === 'main') {
              openingMainUSD -= tx.amount || 0;
            }
            openingActiveUSD += tx.amount || 0;
          } else if (tx.type === 'interest') {
            openingMaturedUSD += tx.amount || 0;
          }
        }
        
        if (user.balances && user.balances.main) {
          const mainMap = user.balances.main;
          const entries = mainMap instanceof Map ? mainMap.entries() : Object.entries(mainMap);
          for (const [asset, balance] of entries) {
            if (balance > 0 && asset !== 'usd') {
              const price = await getCryptoPrice(asset.toUpperCase());
              if (price && price > 0) {
                openingMainUSD += balance * price;
              }
            }
          }
        }
        
        if (user.balances && user.balances.matured) {
          const maturedMap = user.balances.matured;
          const entries = maturedMap instanceof Map ? maturedMap.entries() : Object.entries(maturedMap);
          for (const [asset, balance] of entries) {
            if (balance > 0 && asset !== 'usd') {
              const price = await getCryptoPrice(asset.toUpperCase());
              if (price && price > 0) {
                openingMaturedUSD += balance * price;
              }
            }
          }
        }
        
        let closingMainUSD = 0;
        let closingMaturedUSD = 0;
        let closingActiveUSD = 0;
        
        if (user.balances && user.balances.main) {
          const mainMap = user.balances.main;
          const entries = mainMap instanceof Map ? mainMap.entries() : Object.entries(mainMap);
          for (const [asset, balance] of entries) {
            if (balance > 0 && asset !== 'usd') {
              const price = await getCryptoPrice(asset.toUpperCase());
              if (price && price > 0) {
                closingMainUSD += balance * price;
              }
            }
          }
        }
        
        if (user.balances && user.balances.matured) {
          const maturedMap = user.balances.matured;
          const entries = maturedMap instanceof Map ? maturedMap.entries() : Object.entries(maturedMap);
          for (const [asset, balance] of entries) {
            if (balance > 0 && asset !== 'usd') {
              const price = await getCryptoPrice(asset.toUpperCase());
              if (price && price > 0) {
                closingMaturedUSD += balance * price;
              }
            }
          }
        }
        
        if (user.balances && user.balances.active) {
          const activeMap = user.balances.active;
          const entries = activeMap instanceof Map ? activeMap.entries() : Object.entries(activeMap);
          for (const [asset, balance] of entries) {
            if (balance > 0) {
              closingActiveUSD += balance;
            }
          }
        }
        
        const openingTotalUSD = openingMainUSD + openingActiveUSD + openingMaturedUSD;
        const closingTotalUSD = closingMainUSD + closingActiveUSD + closingMaturedUSD;
        const netChangeUSD = closingTotalUSD - openingTotalUSD;
        
        let totalDeposits = 0;
        let totalWithdrawals = 0;
        let totalFees = 0;
        
        for (const tx of transactions) {
          if (tx.type === 'deposit') {
            totalDeposits += tx.netAmount || tx.amount || 0;
          } else if (tx.type === 'withdrawal') {
            totalWithdrawals += tx.amount || 0;
            if (tx.fee) totalFees += tx.fee;
          } else if (tx.type === 'buy' || tx.type === 'sell') {
            if (tx.fee) totalFees += tx.fee;
          } else if (tx.type === 'investment' && tx.fee) {
            totalFees += tx.fee;
          }
        }
        
        const investmentsInPeriod = await Investment.find({
          user: user._id,
          createdAt: { $gte: periodStart, $lte: periodEnd }
        }).populate('plan');
        
        const maturedInvestments = await Investment.find({
          user: user._id,
          completionDate: { $gte: periodStart, $lte: periodEnd },
          status: 'completed'
        }).populate('plan');
        
        const activeInvestments = await Investment.find({
          user: user._id,
          status: 'active'
        }).populate('plan');
        
        const statement = new FinancialStatement({
          user: user._id,
          statementType: statementType,
          period: {
            startDate: periodStart,
            endDate: periodEnd,
            generationDate: new Date()
          },
          reference: `FS-${statementType.toUpperCase()}-${user._id.toString().slice(-6)}-${Date.now()}`,
          openingBalances: {
            totalUSD: openingTotalUSD,
            mainWalletUSD: openingMainUSD,
            activeWalletUSD: openingActiveUSD,
            maturedWalletUSD: openingMaturedUSD,
            cryptoDetails: [],
            timestamp: periodStart
          },
          closingBalances: {
            totalUSD: closingTotalUSD,
            mainWalletUSD: closingMainUSD,
            activeWalletUSD: closingActiveUSD,
            maturedWalletUSD: closingMaturedUSD,
            cryptoDetails: [],
            timestamp: periodEnd
          },
          netChangeUSD: netChangeUSD,
          transactions: {
            list: transactions.map(tx => ({
              transactionId: tx._id,
              type: tx.type,
              amountUSD: tx.amount,
              asset: tx.asset,
              assetAmount: tx.assetAmount,
              status: tx.status,
              method: tx.method,
              description: tx.details?.description || `${tx.type} transaction`,
              reference: tx.reference,
              feeUSD: tx.fee || 0,
              netAmountUSD: tx.netAmount || tx.amount,
              exchangeRate: tx.exchangeRateAtTime,
              createdAt: tx.createdAt,
              processedAt: tx.processedAt
            })),
            summary: {
              totalDepositsUSD: totalDeposits,
              totalWithdrawalsUSD: totalWithdrawals,
              totalFeesPaidUSD: totalFees,
              totalTransfersUSD: 0,
              count: {
    deposits: transactions.filter(t => t.type === 'deposit').length,
    withdrawals: transactions.filter(t => t.type === 'withdrawal').length,
    transfers: transactions.filter(t => t.type === 'transfer').length,
    refunds: transactions.filter(t => t.type === 'refund').length,
    promos: transactions.filter(t => t.type === 'Promo').length
}
            }
          },
          investments: {
            active: activeInvestments.map(inv => ({
              investmentId: inv._id,
              planName: inv.plan?.name || 'Unknown Plan',
              principalUSD: inv.amount,
              principalBTC: inv.amountBTC,
              expectedReturnUSD: inv.expectedReturn,
              startDate: inv.startDate,
              endDate: inv.endDate,
              status: inv.status
            })),
            started: investmentsInPeriod.map(inv => ({
              investmentId: inv._id,
              planName: inv.plan?.name || 'Unknown Plan',
              amountUSD: inv.amount,
              amountBTC: inv.amountBTC,
              startDate: inv.createdAt,
              expectedReturnUSD: inv.expectedReturn
            })),
            matured: maturedInvestments.map(inv => ({
              investmentId: inv._id,
              planName: inv.plan?.name || 'Unknown Plan',
              initialAmountUSD: inv.originalAmount || inv.amount,
              returnAmountUSD: inv.expectedReturn || inv.amount,
              profitUSD: (inv.expectedReturn || inv.amount) - (inv.originalAmount || inv.amount),
              profitPercentage: inv.returnPercentage || 0,
              completionDate: inv.completionDate || inv.endDate,
              btcPriceAtCompletion: inv.btcPriceAtCompletion
            })),
            summary: {
              totalPrincipalInvestedUSD: investmentsInPeriod.reduce((sum, i) => sum + (i.amount || 0), 0),
              totalReturnsEarnedUSD: maturedInvestments.reduce((sum, i) => sum + ((i.expectedReturn || 0) - (i.originalAmount || 0)), 0),
              totalProfitUSD: maturedInvestments.reduce((sum, i) => sum + ((i.expectedReturn || 0) - (i.originalAmount || 0)), 0),
              totalActiveInvestmentsCount: activeInvestments.length,
              totalActivePrincipalUSD: activeInvestments.reduce((sum, i) => sum + (i.amount || 0), 0)
            }
          },
          summary: {
            totalInflowUSD: totalDeposits,
            totalOutflowUSD: totalWithdrawals,
            netCashFlowUSD: totalDeposits - totalWithdrawals,
            totalProfitUSD: netChangeUSD > 0 ? netChangeUSD : 0,
            totalLossUSD: netChangeUSD < 0 ? Math.abs(netChangeUSD) : 0,
            netProfitUSD: netChangeUSD,
            roiPercentage: openingTotalUSD > 0 ? (netChangeUSD / openingTotalUSD) * 100 : 0
          },
          ipAddress: 'system.cron.job',
          userAgent: 'Automated Statement Generator',
          location: 'System',
          isDelivered: true,
          deliveredAt: new Date()
        });
        
        await statement.save();
        generatedCount++;
        
        console.log(`✅ Generated ${statementType} statement for ${user.email} (Net Change: $${netChangeUSD.toFixed(2)})`);
        
      } catch (userError) {
        console.error(`❌ Failed to generate statement for user ${user._id}:`, userError.message);
        failedCount++;
      }
    }
    
    const elapsedTime = Date.now() - startTime;
    console.log(`🏦 [BANK CRON] Completed in ${elapsedTime}ms`);
    console.log(`   ✅ Generated: ${generatedCount} statements`);
    console.log(`   ❌ Failed: ${failedCount} statements`);
    
  } catch (err) {
    console.error('❌ [BANK CRON] Fatal error in statement generation:', err);
  }
};

