app.get('/api/plans', async (req, res) => {
    try {
    
        const plans = await Plan.find({ isActive: true })
            .sort({ sortOrder: 1, minAmount: 1 })
            .lean();

        if (!plans || plans.length === 0) {
            return res.status(200).json({
                status: 'success',
                data: {
                    plans: [],
                    marketContext: null,
                    userContext: {
                        isLoggedIn: false,
                        canRent: false,
                        kycVerified: false,
                        kycRestricted: false,
                        adminKycRestricted: false,
                        adminTransactionRestricted: false,
                        mainBalance: { usd: 0 },
                        maturedBalance: { usd: 0 },
                        totalPortfolio: { usd: 0 }
                    }
                }
            });
        }

        let btcPrice = 0;
        try {
            const btcPriceResult = await getRealTimeBitcoinPrice();
            btcPrice = btcPriceResult || 0;
        } catch (priceErr) {
            console.error('Failed to fetch BTC price:', priceErr.message);
        }

        // ---- Global electricity settings (used as fallback when a plan does not override) ----
        let globalElectricity = null;
        try {
            const settingsDoc = await SystemSettings.findOne({ type: 'electricity' }).lean();
            globalElectricity = settingsDoc?.electricity || null;
        } catch (elecErr) {
            console.warn('Failed to load electricity SystemSettings for plans endpoint:', elecErr.message);
        }

        const resolvePlanElectricity = (plan) => {
            const baseOverride   = Number(plan.electricityRateBaseUSDPerKWh);
            const demandOverride = Number(plan.electricityRateDemandUSDPerKWh);
            const derateOverride = Number(plan.wallPowerDerating);

            const rateBase = Number.isFinite(baseOverride)
                ? baseOverride
                : (globalElectricity?.rateBaseUSDPerKWh ?? ELEC_FALLBACK.rateBaseUSDPerKWh);

            const rateDemand = Number.isFinite(demandOverride)
                ? demandOverride
                : (globalElectricity?.rateDemandUSDPerKWh ?? ELEC_FALLBACK.rateDemandUSDPerKWh);

            const derating = Number.isFinite(derateOverride)
                ? derateOverride
                : (globalElectricity?.wallPowerDerating ?? ELEC_FALLBACK.wallPowerDerating);

            return {
                rateBaseUSDPerKWh: rateBase,
                rateDemandUSDPerKWh: rateDemand,
                rateAllInUSDPerKWh: rateBase + rateDemand,
                wallPowerDerating: derating
            };
        };

        let userContext = {
            isLoggedIn: false,
            canRent: false,
            kycVerified: false,
            kycRestricted: false,
            adminKycRestricted: false,
            adminTransactionRestricted: false,
            mainBalance: { usd: 0 },
            maturedBalance: { usd: 0 },
            totalPortfolio: { usd: 0 }
        };

        const token = req.headers.authorization?.split(' ')[1] || req.cookies?.jwt;

        if (token) {
            try {
                const decoded = verifyJWT(token);
                const user = await User.findById(decoded.id)
                    .select('balances kycStatus firstName lastName email isVerified');

                if (user) {
                    const kycVerified =
                        user.kycStatus?.identity === 'verified' &&
                        user.kycStatus?.address === 'verified' &&
                        user.kycStatus?.facial === 'verified';

                    const restrictions = await AccountRestrictions.getInstance();
                    const userRestrictionStatus = await UserRestrictionStatus.findOne({ user: user._id }).lean();

                    const adminKycRestricted = !!(userRestrictionStatus && userRestrictionStatus.kyc_restricted);
                    const adminTransactionRestricted = !!(userRestrictionStatus && userRestrictionStatus.transaction_restricted);

                    const adminHasKycPolicy =
                        restrictions.withdraw_limit_no_kyc !== null ||
                        restrictions.invest_limit_no_kyc !== null;

                    const adminHasTransactionPolicy =
                        restrictions.withdraw_limit_no_txn !== null ||
                        restrictions.invest_limit_no_txn !== null;

                    const balances = await calculateRealWalletBalances(user);
                    const mainBalanceUSD = balances.mainUSD || 0;
                    const maturedBalanceUSD = balances.maturedUSD || 0;
                    const totalBalanceUSD = mainBalanceUSD + maturedBalanceUSD;

                    userContext = {
                        isLoggedIn: true,
                        firstName: user.firstName,
                        lastName: user.lastName,
                        email: user.email,
                        isVerified: user.isVerified || false,

                        kycVerified,

                        kycRestricted: adminKycRestricted,
                        adminKycRestricted,
                        adminTransactionRestricted,
                        adminHasKycPolicy,
                        adminHasTransactionPolicy,

                        mainBalance: { usd: mainBalanceUSD },
                        maturedBalance: { usd: maturedBalanceUSD },
                        totalPortfolio: { usd: totalBalanceUSD },

                        canRent: !adminKycRestricted && !adminTransactionRestricted
                    };
                }
            } catch (authErr) {
                console.warn('Auth token invalid for plans endpoint:', authErr.message);
            }
        }

        const enhancedPlans = await Promise.all(plans.map(async (plan) => {
            const planId         = plan._id.toString();
            const planName       = plan.name || 'Mining Contract';
            const planDescription = plan.description || `${planName} SHA-256 ASIC mining contract`;
            const planBadge      = plan.badge || 'Standard';
            const planTier       = plan.tier || 'standard';
            const isPopular      = !!plan.isPopular;
            const isBestValue    = !!plan.isBestValue;

            const color       = plan.color       || '#2ECC71';
            const lightColor  = plan.lightColor  || '#58D68D';
            const bgColor     = plan.bgColor     || 'rgba(46, 204, 113, 0.12)';
            const borderColor = plan.borderColor || 'rgba(46, 204, 113, 0.3)';

            const minAmountUSD  = Number(plan.minAmount) || 0;
            const maxAmountUSD  = Number(plan.maxAmount) || 0;
            const percentage    = Number(plan.percentage) || 0;
            const durationHours = Number(plan.duration) || 0;
            const durationDays  = durationHours / 24;

            const cycleFeePercent =
                (typeof plan.cycleFeePercent === 'number' && plan.cycleFeePercent >= 0)
                    ? plan.cycleFeePercent
                    : CYCLE_FEE_PERCENT;

            const autoCompoundOptions =
                Array.isArray(plan.autoCompoundOptions) && plan.autoCompoundOptions.length > 0
                    ? plan.autoCompoundOptions
                    : [1, 3, 6, 9, 12];

            const defaultAutoCompoundMonths =
                typeof plan.defaultAutoCompoundMonths === 'number'
                    ? plan.defaultAutoCompoundMonths
                    : (autoCompoundOptions[0] || 1);

            const minAutoCompoundMonths =
                typeof plan.minAutoCompoundMonths === 'number'
                    ? plan.minAutoCompoundMonths
                    : (autoCompoundOptions[0] || 1);

            const maxAutoCompoundMonths =
                typeof plan.maxAutoCompoundMonths === 'number'
                    ? plan.maxAutoCompoundMonths
                    : (autoCompoundOptions[autoCompoundOptions.length - 1] || 12);

            const allowAutoCompound = plan.allowAutoCompound !== false;

            const minAmountBTC = btcPrice > 0 ? minAmountUSD / btcPrice : 0;
            const maxAmountBTC = btcPrice > 0 ? maxAmountUSD / btcPrice : 0;

            const minNetPrincipal = minAmountUSD * (1 - cycleFeePercent / 100);
            const maxNetPrincipal = maxAmountUSD * (1 - cycleFeePercent / 100);

            const minHashpower = calculateHashpower(minNetPrincipal, percentage, durationHours, btcPrice);
            const maxHashpower = calculateHashpower(maxNetPrincipal, percentage, durationHours, btcPrice);

            const formatHashpower = (v) => {
                if (!v || v <= 0) return '0';
                if (v >= 1000) return v.toLocaleString(undefined, { maximumFractionDigits: 0 });
                if (v >= 1)    return v.toFixed(1);
                return v.toFixed(3);
            };

            const hashrateUnit = plan.hashrateUnit || 'TH/s';

            const hashrateRangeDisplay =
                (minHashpower > 0 && maxHashpower > 0)
                    ? (plan.hashrateDisplayOverride ||
                       `${formatHashpower(minHashpower)} - ${formatHashpower(maxHashpower)} ${hashrateUnit}`)
                    : (plan.hashrateDisplayOverride || 'Calculating...');

            const features = Array.isArray(plan.features) ? plan.features : [];

            const btcRange = btcPrice > 0
                ? `${minAmountBTC.toFixed(5)} - ${maxAmountBTC.toFixed(5)} BTC`
                : `${minAmountUSD.toFixed(0)} - ${maxAmountUSD.toFixed(0)} USD`;

            // ---------- Hardware + efficiency identity (DB-backed) ----------
            const hardwareModel  = plan.hardwareModel || '';
            const hardwareVendor = plan.hardwareVendor || '';
            const joulesPerTH    = Number(plan.joulesPerTH) > 0
                ? Number(plan.joulesPerTH)
                : 15.0;

            // ---------- Resolved electricity cost basis ----------
            const resolvedElectricity = resolvePlanElectricity(plan);

            // ---------- Informational power-cost envelope (admin/debug only) ----------
            const minPowerCostPerDayUSD =
                (minHashpower * joulesPerTH * resolvedElectricity.wallPowerDerating * 24 / 1000)
                * resolvedElectricity.rateAllInUSDPerKWh;

            const maxPowerCostPerDayUSD =
                (maxHashpower * joulesPerTH * resolvedElectricity.wallPowerDerating * 24 / 1000)
                * resolvedElectricity.rateAllInUSDPerKWh;

            let buttonState   = 'login';
            let buttonText    = 'Login to Rent Hashpower';
            let buttonTooltip = 'Please login to rent hashpower';
            let canRent       = false;

            if (userContext.isLoggedIn) {
                if (userContext.adminKycRestricted) {
                    buttonState   = 'kyc_required';
                    buttonText    = 'Complete KYC';
                    buttonTooltip = 'KYC verification is required to rent hashpower (admin-enforced restriction)';
                }
                else if (userContext.adminTransactionRestricted) {
                    buttonState   = 'transaction_required';
                    buttonText    = 'Complete a Transaction';
                    buttonTooltip = 'An admin-enforced transaction restriction is active on your account';
                }
                else {
                    const totalUserBalance = (userContext.mainBalance?.usd || 0) + (userContext.maturedBalance?.usd || 0);

                    if (totalUserBalance >= minAmountUSD) {
                        canRent       = true;
                        buttonState   = 'rent';
                        buttonText    = 'Rent Hashpower';
                        buttonTooltip = `Rent ${planName} mining capacity`;
                    } else {
                        buttonState   = 'insufficient';
                        buttonText    = `Need $${minAmountUSD.toLocaleString()}`;
                        buttonTooltip = `Required balance for this plan: $${minAmountUSD.toLocaleString()}. Your balance: $${totalUserBalance.toLocaleString()}`;
                    }
                }
            }

            return {
                id: planId,
                _id: planId,

                name: planName,
                badge: planBadge,
                description: planDescription,
                tier: planTier,

                isPopular,
                isBestValue,

                bgColor,
                color,
                borderColor,
                lightColor,

                percentage,
                duration: {
                    hours: durationHours,
                    days: durationDays
                },
                minAmount: { usd: minAmountUSD },
                maxAmount: { usd: maxAmountUSD },
                minAmountBTC,
                maxAmountBTC,
                btcRange,

                features,

                minHashpower: formatHashpower(minHashpower) + ' ' + hashrateUnit,
                maxHashpower: formatHashpower(maxHashpower) + ' ' + hashrateUnit,
                hashrate: {
                    min: parseFloat(minHashpower.toFixed(4)),
                    max: parseFloat(maxHashpower.toFixed(4)),
                    unit: hashrateUnit,
                    display: hashrateRangeDisplay
                },

                // ---------- Hardware + efficiency for the card ----------
                hardwareModel,
                hardwareVendor,
                joulesPerTH,

                // ---------- Resolved electricity basis for transparency / future settlement ----------
                electricityRate: {
                    baseUSDPerKWh:   resolvedElectricity.rateBaseUSDPerKWh,
                    demandUSDPerKWh: resolvedElectricity.rateDemandUSDPerKWh,
                    allInUSDPerKWh:  resolvedElectricity.rateAllInUSDPerKWh
                },
                wallPowerDerating: resolvedElectricity.wallPowerDerating,

                // ---------- Admin/debug only — not rendered on cards ----------
                powerCostPerDayUSD: {
                    min: parseFloat(minPowerCostPerDayUSD.toFixed(2)),
                    max: parseFloat(maxPowerCostPerDayUSD.toFixed(2))
                },

                autoCompound: {
                    allow: allowAutoCompound,
                    options: autoCompoundOptions,
                    defaultMonths: defaultAutoCompoundMonths,
                    minMonths: minAutoCompoundMonths,
                    maxMonths: maxAutoCompoundMonths
                },

                cycleFeePercent,

                buttonState,
                buttonText,
                buttonTooltip,
                canRent
            };
        }));

        const response = {
            status: 'success',
            data: {
                plans: enhancedPlans,
                marketContext: {
                    btcPrice,
                    timestamp: new Date().toISOString()
                },
                userContext
            }
        };

        res.set('Cache-Control', 'public, max-age=60');
        res.status(200).json(response);

    } catch (err) {
        console.error('Plans endpoint error:', err);
        res.status(500).json({
            status: 'error',
            message: 'Failed to load mining contracts',
            error: process.env.NODE_ENV === 'development' ? err.message : undefined
        });
    }
});






app.post('/api/mining/calculator', async (req, res) => {
    const startTime = Date.now();

    try {
        // ------------------------------------------------------------------
        // 1. PARSE REQUEST BODY (must match frontend payload exactly)
        // ------------------------------------------------------------------
        const {
            investmentAmount,
            hashrateTH,
            durationMonths,
            calculationType
        } = req.body || {};

        const calcType = calculationType || 'investment';

        const parsedDurationMonths =
            (durationMonths === undefined || durationMonths === null || durationMonths === '')
                ? 0
                : parseInt(durationMonths, 10);

        // ------------------------------------------------------------------
        // 2. VALIDATION
        // ------------------------------------------------------------------
        const errors = [];

        if (calculationType && !['investment', 'hashrate', 'duration', 'single_cycle'].includes(calculationType)) {
            errors.push('Invalid calculation type.');
        }

        if (investmentAmount !== undefined && investmentAmount !== null && investmentAmount !== '') {
            const amount = parseFloat(investmentAmount);
            if (isNaN(amount) || amount < 50) errors.push('Minimum investment amount is $50.');
            if (amount > 1000000) errors.push('Maximum investment amount is $1,000,000.');
        }

        if (parsedDurationMonths !== 0 && ![1, 3, 6, 9, 12].includes(parsedDurationMonths)) {
            errors.push('Duration must be 0 (single cycle) or one of: 1, 3, 6, 9, 12 months.');
        }

        if (hashrateTH !== undefined && hashrateTH !== null && hashrateTH !== '') {
            const th = parseFloat(hashrateTH);
            if (isNaN(th) || th <= 0) errors.push('Hashrate must be a positive number.');
        }

        const hasAmount = investmentAmount !== undefined && investmentAmount !== null && investmentAmount !== '';
        const hasHashrate = hashrateTH !== undefined && hashrateTH !== null && hashrateTH !== '';

        if (calcType === 'single_cycle' && !hasAmount && !hasHashrate) {
            errors.push('Single-cycle calculation requires investmentAmount or hashrateTH.');
        }

        if (errors.length > 0) {
            return res.status(400).json({
                status: 'fail',
                success: false,
                message: 'Validation failed',
                errors
            });
        }

        // ------------------------------------------------------------------
        // 3. FETCH BTC PRICE (fail fast, no fallbacks)
        // ------------------------------------------------------------------
        let btcPrice;
        try {
            btcPrice = await getCryptoPrice('BTC');
        } catch (priceError) {
            console.error('BTC price fetch failed for calculator:', priceError.message);
            return res.status(503).json({
                status: 'error',
                success: false,
                message: 'Unable to fetch current market data. Please try again later.',
                retryAfter: 10
            });
        }

        if (!btcPrice || btcPrice <= 0) {
            return res.status(503).json({
                status: 'error',
                success: false,
                message: 'Unable to fetch current market data. Please try again later.',
                retryAfter: 10
            });
        }

        // ------------------------------------------------------------------
        // 4. LOAD ACTIVE PLANS
        // ------------------------------------------------------------------
        const plans = await Plan.find({ isActive: true }).sort({ minAmount: 1 }).lean();

        if (!plans || plans.length === 0) {
            return res.status(503).json({
                status: 'error',
                success: false,
                message: 'No mining contracts available at this time.'
            });
        }

        // ------------------------------------------------------------------
        // 5. RESOLVE GLOBAL ELECTRICITY RATES (once per request)
        // ------------------------------------------------------------------
        const globalRates = await resolveElectricityRates(null);

        const btcLogoUrl = getCryptoLogo('BTC');

        // ------------------------------------------------------------------
        // 6. FORMATTING HELPERS
        // ------------------------------------------------------------------
        const formatUSD = (value) => {
            const n = Number(value);
            if (!Number.isFinite(n)) return '$0.00';
            return '$' + n.toLocaleString('en-US', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
            });
        };

        const formatBTC = (value) => {
            const n = Number(value);
            if (!Number.isFinite(n)) return '0.00000000';
            return n.toFixed(8);
        };

        const buildMoney = (btcValue, usdValue) => {
            const btc = Number.isFinite(Number(btcValue)) ? Number(btcValue) : 0;
            const usd = Number.isFinite(Number(usdValue)) ? Number(usdValue) : 0;
            const btcFormatted = formatBTC(btc);
            const usdFormatted = formatUSD(usd);
            return {
                btc: parseFloat(btc.toFixed(8)),
                btcFormatted,
                usd: parseFloat(usd.toFixed(2)),
                usdFormatted,
                display: `${btcFormatted} BTC ≈ ${usdFormatted}`,
                logoUrl: btcLogoUrl
            };
        };

        const resolveCycleFeePercent = (plan) => {
            if (plan && typeof plan.cycleFeePercent === 'number' && plan.cycleFeePercent >= 0) {
                return plan.cycleFeePercent;
            }
            return CYCLE_FEE_PERCENT;
        };

        const resolvePlanRates = (plan) => {
            const baseOverride = Number(plan && plan.electricityRateBaseUSDPerKWh);
            const demandOverride = Number(plan && plan.electricityRateDemandUSDPerKWh);
            const derateOverride = Number(plan && plan.wallPowerDerating);

            const rateBase = Number.isFinite(baseOverride) && baseOverride > 0
                ? baseOverride
                : globalRates.rateBaseUSDPerKWh;

            const rateDemand = Number.isFinite(demandOverride) && demandOverride > 0
                ? demandOverride
                : globalRates.rateDemandUSDPerKWh;

            const derating = Number.isFinite(derateOverride) && derateOverride >= 1
                ? derateOverride
                : globalRates.wallPowerDerating;

            return {
                rateBaseUSDPerKWh: rateBase,
                rateDemandUSDPerKWh: rateDemand,
                rateAllInUSDPerKWh: rateBase + rateDemand,
                wallPowerDerating: derating
            };
        };

        const computePowerCostUSD = (hashpowerTH, joulesPerTH, durationHours, rates) => {
            if (!hashpowerTH || hashpowerTH <= 0) return 0;
            if (!joulesPerTH || joulesPerTH <= 0) return 0;
            if (!durationHours || durationHours <= 0) return 0;

            const wallWatts = hashpowerTH * joulesPerTH * rates.wallPowerDerating;
            const kwh = (wallWatts * durationHours) / 1000;
            return kwh * rates.rateAllInUSDPerKWh;
        };

        const buildElectricityBlock = (hashpowerTH, plan, durationHours, rates, cycles) => {
            const jPerTH = Number(plan.joulesPerTH) || 15.0;
            const perCycleUSD = computePowerCostUSD(hashpowerTH, jPerTH, durationHours, rates);
            const totalUSD = perCycleUSD * (cycles || 1);
            const perCycleBTC = btcPrice > 0 ? perCycleUSD / btcPrice : 0;
            const totalBTC = btcPrice > 0 ? totalUSD / btcPrice : 0;
            const kwhPerCycle = (hashpowerTH * jPerTH * rates.wallPowerDerating * durationHours) / 1000;

            return {
                hardwareModel: plan.hardwareModel || '',
                hardwareVendor: plan.hardwareVendor || '',

                energyEfficiency: {
                    joulesPerTH: jPerTH,
                    label: `${jPerTH.toFixed(1)} J/TH`
                },

                powerCostPerCycle: {
                    usd: parseFloat(perCycleUSD.toFixed(2)),
                    usdFormatted: formatUSD(perCycleUSD),
                    btc: parseFloat(perCycleBTC.toFixed(8)),
                    btcFormatted: formatBTC(perCycleBTC),
                    display: `${formatUSD(perCycleUSD)} / cycle`
                },

                electricityRate: {
                    baseUSDPerKWh: rates.rateBaseUSDPerKWh,
                    demandUSDPerKWh: rates.rateDemandUSDPerKWh,
                    allInUSDPerKWh: rates.rateAllInUSDPerKWh,
                    display: `$${rates.rateAllInUSDPerKWh.toFixed(3)}/kWh`
                },

                electricityFee: {
                    usd: parseFloat(totalUSD.toFixed(2)),
                    usdFormatted: formatUSD(totalUSD),
                    btc: parseFloat(totalBTC.toFixed(8)),
                    btcFormatted: formatBTC(totalBTC),
                    display: `${formatUSD(totalUSD)} total`
                },

                wallPowerDerating: rates.wallPowerDerating,
                durationHours,
                cycles: cycles || 1,
                kwhPerCycle: parseFloat(kwhPerCycle.toFixed(4)),

                // Flat aliases for backwards compatibility
                joulesPerTH: jPerTH,
                rateBaseUSDPerKWh: rates.rateBaseUSDPerKWh,
                rateDemandUSDPerKWh: rates.rateDemandUSDPerKWh,
                rateAllInUSDPerKWh: rates.rateAllInUSDPerKWh,
                perCycleUSD: parseFloat(perCycleUSD.toFixed(2)),
                perCycleBTC: parseFloat(perCycleBTC.toFixed(8)),
                totalUSD: parseFloat(totalUSD.toFixed(2)),
                totalBTC: parseFloat(totalBTC.toFixed(8))
            };
        };

        // ------------------------------------------------------------------
        // 7. PROJECTION CALCULATORS
        // ------------------------------------------------------------------
        const calculateSingleCycleProjection = (principalUSD, plan, currentBtcPrice) => {
            const planReturnDecimal = plan.percentage / 100;
            const durationHours = Number(plan.duration) || 0;
            const feePercent = resolveCycleFeePercent(plan);
            const feeDecimal = feePercent / 100;
            const rates = resolvePlanRates(plan);

            const grossPrincipalUSD = principalUSD;
            const grossPrincipalBTC = principalUSD / currentBtcPrice;

            const firstCycleFeeUSD = grossPrincipalUSD * feeDecimal;
            const firstCycleFeeBTC = grossPrincipalBTC * feeDecimal;

            const netPrincipalUSD = grossPrincipalUSD - firstCycleFeeUSD;
            const netPrincipalBTC = grossPrincipalBTC - firstCycleFeeBTC;

            const hashpower = calculateHashpower(
                netPrincipalUSD,
                plan.percentage,
                durationHours,
                currentBtcPrice
            );

            const totalReturnUSD = netPrincipalUSD * (1 + planReturnDecimal);
            const totalReturnBTC = netPrincipalBTC * (1 + planReturnDecimal);

            const totalProfitUSD = totalReturnUSD - netPrincipalUSD;
            const totalProfitBTC = totalReturnBTC - netPrincipalBTC;

            const electricity = buildElectricityBlock(hashpower, plan, durationHours, rates, 1);

            const netAfterPowerUSD = totalProfitUSD - electricity.electricityFee.usd;
            const netAfterPowerBTC = totalProfitBTC - electricity.electricityFee.btc;

            const roiPercent = grossPrincipalUSD > 0
                ? (netAfterPowerUSD / grossPrincipalUSD) * 100
                : 0;

            return {
                payoutModel: 'single_cycle',

                principal: buildMoney(grossPrincipalBTC, grossPrincipalUSD),
                netPrincipal: buildMoney(netPrincipalBTC, netPrincipalUSD),
                firstCycleFee: buildMoney(firstCycleFeeBTC, firstCycleFeeUSD),
                totalFees: buildMoney(firstCycleFeeBTC, firstCycleFeeUSD),
                hashpower,

                hardwareModel: plan.hardwareModel || '',
                hardwareVendor: plan.hardwareVendor || '',
                energyEfficiency: electricity.energyEfficiency,
                powerCostPerCycle: electricity.powerCostPerCycle,
                electricityRate: electricity.electricityRate,
                electricityFee: electricity.electricityFee,
                electricity,

                totalReturn: buildMoney(totalReturnBTC, totalReturnUSD),
                totalPayout: buildMoney(totalReturnBTC, totalReturnUSD),
                totalProfit: buildMoney(totalProfitBTC, totalProfitUSD),

                netAfterPower: buildMoney(netAfterPowerBTC, netAfterPowerUSD),
                netAfterPowerUSD: parseFloat(netAfterPowerUSD.toFixed(2)),
                netAfterPowerBTC: parseFloat(netAfterPowerBTC.toFixed(8)),

                monthlyNetPayout: buildMoney(netAfterPowerBTC, netAfterPowerUSD),
                finalPayout: buildMoney(netAfterPowerBTC, netAfterPowerUSD),
                netMonthlyPayout: buildMoney(netAfterPowerBTC, netAfterPowerUSD),

                principalUSD: parseFloat(grossPrincipalUSD.toFixed(2)),
                principalBTC: parseFloat(grossPrincipalBTC.toFixed(8)),
                firstCycleFeeUSD: parseFloat(firstCycleFeeUSD.toFixed(2)),
                firstCycleFeeBTC: parseFloat(firstCycleFeeBTC.toFixed(8)),
                netPrincipalUSD: parseFloat(netPrincipalUSD.toFixed(2)),
                netPrincipalBTC: parseFloat(netPrincipalBTC.toFixed(8)),

                totalReturnUSD: parseFloat(totalReturnUSD.toFixed(2)),
                totalReturnBTC: parseFloat(totalReturnBTC.toFixed(8)),
                totalPayoutUSD: parseFloat(totalReturnUSD.toFixed(2)),
                totalPayoutBTC: parseFloat(totalReturnBTC.toFixed(8)),
                totalProfitUSD: parseFloat(totalProfitUSD.toFixed(2)),
                totalProfitBTC: parseFloat(totalProfitBTC.toFixed(8)),

                monthlyNetPayoutUSD: parseFloat(netAfterPowerUSD.toFixed(2)),
                monthlyNetPayoutBTC: parseFloat(netAfterPowerBTC.toFixed(8)),
                finalPayoutUSD: parseFloat(netAfterPowerUSD.toFixed(2)),
                finalPayoutBTC: parseFloat(netAfterPowerBTC.toFixed(8)),

                totalFeesUSD: parseFloat(firstCycleFeeUSD.toFixed(2)),
                totalFeesBTC: parseFloat(firstCycleFeeBTC.toFixed(8)),

                totalElectricityUSD: electricity.electricityFee.usd,
                totalElectricityBTC: electricity.electricityFee.btc,

                durationHours,
                cycleDurationHours: durationHours,
                planDurationHours: durationHours,
                planDurationDays: parseFloat((durationHours / 24).toFixed(2)),
                durationMonths: 0,

                cycleFeePercent: feePercent,

                roiPercent: parseFloat(roiPercent.toFixed(2)),
                roiPerMonth: 0,

                monthlyBreakdown: [],
                payoutPerMonth: [{
                    month: 1,
                    isFinalMonth: true,
                    startingPrincipal: buildMoney(grossPrincipalBTC, grossPrincipalUSD),
                    endingValue: buildMoney(totalReturnBTC, totalReturnUSD),
                    payout: buildMoney(netAfterPowerBTC, netAfterPowerUSD),
                    profit: buildMoney(netAfterPowerBTC, netAfterPowerUSD),
                    cyclesInMonth: 1,
                    feesPaid: buildMoney(firstCycleFeeBTC, firstCycleFeeUSD),
                    electricityPaid: buildMoney(electricity.electricityFee.btc, electricity.electricityFee.usd),

                    startingPrincipalUSD: parseFloat(grossPrincipalUSD.toFixed(2)),
                    startingPrincipalBTC: parseFloat(grossPrincipalBTC.toFixed(8)),
                    endingValueUSD: parseFloat(totalReturnUSD.toFixed(2)),
                    endingValueBTC: parseFloat(totalReturnBTC.toFixed(8)),
                    payoutUSD: parseFloat(netAfterPowerUSD.toFixed(2)),
                    payoutBTC: parseFloat(netAfterPowerBTC.toFixed(8)),
                    profitUSD: parseFloat(netAfterPowerUSD.toFixed(2)),
                    profitBTC: parseFloat(netAfterPowerBTC.toFixed(8)),
                    feesPaidUSD: parseFloat(firstCycleFeeUSD.toFixed(2)),
                    feesPaidBTC: parseFloat(firstCycleFeeBTC.toFixed(8)),
                    electricityPaidUSD: electricity.electricityFee.usd,
                    electricityPaidBTC: electricity.electricityFee.btc,

                    note: `Single-cycle contract of ${durationHours} hours pays principal + profit at cycle end, net of electricity`
                }]
            };
        };

        const calculateMultiMonthProjection = (principalUSD, plan, months, currentBtcPrice) => {
            const planReturnDecimal = plan.percentage / 100;
            const durationHours = Number(plan.duration) || 0;
            const cyclesPerMonth = calculateCyclesPerMonth(durationHours);
            const totalMonths = months;
            const feePercent = resolveCycleFeePercent(plan);
            const feeDecimal = feePercent / 100;
            const rates = resolvePlanRates(plan);

            const grossPrincipalUSD = principalUSD;
            const grossPrincipalBTC = principalUSD / currentBtcPrice;

            const firstCycleFeeUSD = grossPrincipalUSD * feeDecimal;
            const firstCycleFeeBTC = grossPrincipalBTC * feeDecimal;
            const firstNetPrincipalUSD = grossPrincipalUSD - firstCycleFeeUSD;
            const firstNetPrincipalBTC = grossPrincipalBTC - firstCycleFeeBTC;

            const initialHashpower = calculateHashpower(
                firstNetPrincipalUSD,
                plan.percentage,
                durationHours,
                currentBtcPrice
            );

            const totalCycles = cyclesPerMonth * totalMonths;
            const electricity = buildElectricityBlock(
                initialHashpower,
                plan,
                durationHours,
                rates,
                totalCycles
            );

            const electricityPerCycleUSD = electricity.powerCostPerCycle.usd;
            const electricityPerCycleBTC = electricity.powerCostPerCycle.btc;

            let totalFeesUSD = 0;
            let totalFeesBTC = 0;
            let totalElectricityUSD = 0;
            let totalElectricityBTC = 0;
            let totalPayoutUSD = 0;
            let totalPayoutBTC = 0;

            const monthlyBreakdown = [];

            let monthStartingPrincipalUSD = grossPrincipalUSD;
            let monthStartingPrincipalBTC = grossPrincipalBTC;

            for (let month = 1; month <= totalMonths; month++) {
                const isFinalMonth = month === totalMonths;

                let monthIncomingUSD = monthStartingPrincipalUSD;
                let monthIncomingBTC = monthStartingPrincipalBTC;
                let monthFeesUSD = 0;
                let monthFeesBTC = 0;
                let monthElectricityUSD = 0;
                let monthElectricityBTC = 0;
                let monthEndingValueUSD = monthStartingPrincipalUSD;
                let monthEndingValueBTC = monthStartingPrincipalBTC;

                for (let cycle = 1; cycle <= cyclesPerMonth; cycle++) {
                    const cycleFeeUSD = monthIncomingUSD * feeDecimal;
                    const cycleFeeBTC = monthIncomingBTC * feeDecimal;

                    monthFeesUSD += cycleFeeUSD;
                    monthFeesBTC += cycleFeeBTC;

                    const cycleNetUSD = monthIncomingUSD - cycleFeeUSD;
                    const cycleNetBTC = monthIncomingBTC - cycleFeeBTC;

                    const cycleReturnUSD = cycleNetUSD * (1 + planReturnDecimal);
                    const cycleReturnBTC = cycleNetBTC * (1 + planReturnDecimal);

                    monthIncomingUSD = cycleReturnUSD;
                    monthIncomingBTC = cycleReturnBTC;
                    monthEndingValueUSD = cycleReturnUSD;
                    monthEndingValueBTC = cycleReturnBTC;

                    monthElectricityUSD += electricityPerCycleUSD;
                    monthElectricityBTC += electricityPerCycleBTC;
                }

                const monthProfitUSD = monthEndingValueUSD - monthStartingPrincipalUSD - monthElectricityUSD;
                const monthProfitBTC = monthEndingValueBTC - monthStartingPrincipalBTC - monthElectricityBTC;

                const monthPayoutUSD = isFinalMonth ? (monthEndingValueUSD - monthElectricityUSD) : monthProfitUSD;
                const monthPayoutBTC = isFinalMonth ? (monthEndingValueBTC - monthElectricityBTC) : monthProfitBTC;

                totalFeesUSD += monthFeesUSD;
                totalFeesBTC += monthFeesBTC;
                totalElectricityUSD += monthElectricityUSD;
                totalElectricityBTC += monthElectricityBTC;
                totalPayoutUSD += monthPayoutUSD;
                totalPayoutBTC += monthPayoutBTC;

                monthlyBreakdown.push({
                    month,
                    isFinalMonth,

                    startingPrincipal: buildMoney(monthStartingPrincipalBTC, monthStartingPrincipalUSD),
                    endingValue: buildMoney(monthEndingValueBTC, monthEndingValueUSD),
                    payout: buildMoney(monthPayoutBTC, monthPayoutUSD),
                    profit: buildMoney(monthProfitBTC, monthProfitUSD),
                    cyclesInMonth: cyclesPerMonth,
                    feesPaid: buildMoney(monthFeesBTC, monthFeesUSD),
                    electricityPaid: buildMoney(monthElectricityBTC, monthElectricityUSD),

                    startingPrincipalUSD: parseFloat(monthStartingPrincipalUSD.toFixed(2)),
                    startingPrincipalBTC: parseFloat(monthStartingPrincipalBTC.toFixed(8)),
                    endingValueUSD: parseFloat(monthEndingValueUSD.toFixed(2)),
                    endingValueBTC: parseFloat(monthEndingValueBTC.toFixed(8)),
                    payoutUSD: parseFloat(monthPayoutUSD.toFixed(2)),
                    payoutBTC: parseFloat(monthPayoutBTC.toFixed(8)),
                    profitUSD: parseFloat(monthProfitUSD.toFixed(2)),
                    profitBTC: parseFloat(monthProfitBTC.toFixed(8)),
                    feesPaidUSD: parseFloat(monthFeesUSD.toFixed(2)),
                    feesPaidBTC: parseFloat(monthFeesBTC.toFixed(8)),
                    electricityPaidUSD: parseFloat(monthElectricityUSD.toFixed(2)),
                    electricityPaidBTC: parseFloat(monthElectricityBTC.toFixed(8))
                });

                monthStartingPrincipalUSD = firstNetPrincipalUSD;
                monthStartingPrincipalBTC = firstNetPrincipalBTC;
            }

            const lastMonth = monthlyBreakdown[monthlyBreakdown.length - 1];
            const monthlyNetPayoutUSD = lastMonth.profitUSD;
            const monthlyNetPayoutBTC = lastMonth.profitBTC;

            const totalProfitUSD = totalPayoutUSD - grossPrincipalUSD;
            const totalProfitBTC = totalPayoutBTC - grossPrincipalBTC;

            const roiPercent = grossPrincipalUSD > 0
                ? (totalProfitUSD / grossPrincipalUSD) * 100
                : 0;
            const roiPerMonth = totalMonths > 0 ? roiPercent / totalMonths : 0;

            const netAfterPowerUSD = totalProfitUSD - totalElectricityUSD;
            const netAfterPowerBTC = totalProfitBTC - totalElectricityBTC;

            return {
                payoutModel: 'profit_only_until_final_month',

                principal: buildMoney(grossPrincipalBTC, grossPrincipalUSD),
                netPrincipal: buildMoney(firstNetPrincipalBTC, firstNetPrincipalUSD),
                firstCycleFee: buildMoney(firstCycleFeeBTC, firstCycleFeeUSD),
                totalFees: buildMoney(totalFeesBTC, totalFeesUSD),
                hashpower: initialHashpower,

                hardwareModel: plan.hardwareModel || '',
                hardwareVendor: plan.hardwareVendor || '',
                energyEfficiency: electricity.energyEfficiency,
                powerCostPerCycle: electricity.powerCostPerCycle,
                electricityRate: electricity.electricityRate,
                electricityFee: electricity.electricityFee,
                electricity,

                totalReturn: buildMoney(totalPayoutBTC, totalPayoutUSD),
                totalPayout: buildMoney(totalPayoutBTC, totalPayoutUSD),
                totalProfit: buildMoney(totalProfitBTC, totalProfitUSD),

                netAfterPower: buildMoney(netAfterPowerBTC, netAfterPowerUSD),
                netAfterPowerUSD: parseFloat(netAfterPowerUSD.toFixed(2)),
                netAfterPowerBTC: parseFloat(netAfterPowerBTC.toFixed(8)),

                monthlyNetPayout: buildMoney(monthlyNetPayoutBTC, monthlyNetPayoutUSD),
                finalPayout: buildMoney(monthlyNetPayoutBTC, monthlyNetPayoutUSD),
                netMonthlyPayout: buildMoney(monthlyNetPayoutBTC, monthlyNetPayoutUSD),

                principalUSD: parseFloat(grossPrincipalUSD.toFixed(2)),
                principalBTC: parseFloat(grossPrincipalBTC.toFixed(8)),
                firstCycleFeeUSD: parseFloat(firstCycleFeeUSD.toFixed(2)),
                firstCycleFeeBTC: parseFloat(firstCycleFeeBTC.toFixed(8)),
                netPrincipalUSD: parseFloat(firstNetPrincipalUSD.toFixed(2)),
                netPrincipalBTC: parseFloat(firstNetPrincipalBTC.toFixed(8)),

                totalReturnUSD: parseFloat(totalPayoutUSD.toFixed(2)),
                totalReturnBTC: parseFloat(totalPayoutBTC.toFixed(8)),
                totalPayoutUSD: parseFloat(totalPayoutUSD.toFixed(2)),
                totalPayoutBTC: parseFloat(totalPayoutBTC.toFixed(8)),
                totalProfitUSD: parseFloat(totalProfitUSD.toFixed(2)),
                totalProfitBTC: parseFloat(totalProfitBTC.toFixed(8)),

                monthlyNetPayoutUSD: parseFloat(monthlyNetPayoutUSD.toFixed(2)),
                monthlyNetPayoutBTC: parseFloat(monthlyNetPayoutBTC.toFixed(8)),
                finalPayoutUSD: parseFloat(monthlyNetPayoutUSD.toFixed(2)),
                finalPayoutBTC: parseFloat(monthlyNetPayoutBTC.toFixed(8)),

                totalFeesUSD: parseFloat(totalFeesUSD.toFixed(2)),
                totalFeesBTC: parseFloat(totalFeesBTC.toFixed(8)),

                totalElectricityUSD: parseFloat(totalElectricityUSD.toFixed(2)),
                totalElectricityBTC: parseFloat(totalElectricityBTC.toFixed(8)),

                durationHours,
                cycleDurationHours: durationHours,
                planDurationHours: durationHours,
                planDurationDays: parseFloat((durationHours / 24).toFixed(2)),
                cyclesPerMonth,
                totalCycles: cyclesPerMonth * totalMonths,
                durationMonths: totalMonths,
                cycleFeePercent: feePercent,

                roiPercent: parseFloat(roiPercent.toFixed(2)),
                roiPerMonth: parseFloat(roiPerMonth.toFixed(2)),

                monthlyBreakdown,
                payoutPerMonth: monthlyBreakdown
            };
        };

        const calculateContractProjection = (principalUSD, plan, months, currentBtcPrice) => {
            if (!months || months === 0) {
                return calculateSingleCycleProjection(principalUSD, plan, currentBtcPrice);
            }
            return calculateMultiMonthProjection(principalUSD, plan, months, currentBtcPrice);
        };

        const buildRecommendedDuration = (plan, months) => {
            const durationHours = Number(plan.duration) || 0;
            const isSingle = !months || months === 0;

            const cyclesPerMonth = isSingle ? null : calculateCyclesPerMonth(durationHours);
            const totalCycles = isSingle ? 1 : months * (cyclesPerMonth || 1);

            const label = isSingle
                ? `${durationHours} hours`
                : `${months} Month${months > 1 ? 's' : ''} (${durationHours}h cycle)`;

            return {
                isSingleCycle: isSingle,
                durationMonths: isSingle ? 0 : months,
                durationHours,
                durationDays: parseFloat((durationHours / 24).toFixed(2)),
                cyclesPerMonth,
                totalCycles,
                label,
                payoutModel: isSingle
                    ? 'single_cycle'
                    : 'profit_only_until_final_month',
                payoutComposition: isSingle
                    ? 'principal_and_profit_at_cycle_end'
                    : `profit_only_for_months_1_to_${months - 1}_then_principal_and_profit_at_month_${months}`
            };
        };

        const calculateCostPerTH = (plan, currentBtcPrice) => {
            const minInvestment = plan.minAmount;
            const feePercent = resolveCycleFeePercent(plan);
            const feeUSD = minInvestment * (feePercent / 100);
            const netPrincipalUSD = minInvestment - feeUSD;

            const hashpower = calculateHashpower(
                netPrincipalUSD,
                plan.percentage,
                plan.duration,
                currentBtcPrice
            );

            if (hashpower <= 0) return null;

            const costPerTHUSD = minInvestment / hashpower;
            return {
                minInvestment,
                hashpowerAtMin: hashpower,
                costPerTH: buildMoney(costPerTHUSD / currentBtcPrice, costPerTHUSD),
                costPerTHUSD: parseFloat(costPerTHUSD.toFixed(2)),
                costPerTHBTC: parseFloat((costPerTHUSD / currentBtcPrice).toFixed(8))
            };
        };

        // ------------------------------------------------------------------
        // 8. PLAN METRICS (shared across calc types)
        // ------------------------------------------------------------------
        const planMetrics = plans.map(plan => {
            const costData = calculateCostPerTH(plan, btcPrice);
            const cyclesPerMonth = calculateCyclesPerMonth(plan.duration);
            const rates = resolvePlanRates(plan);

            return {
                planId: plan._id.toString(),
                name: plan.name,
                description: plan.description,
                percentage: plan.percentage,
                durationHours: plan.duration,
                durationDays: parseFloat((plan.duration / 24).toFixed(2)),
                cyclesPerMonth,

                hardwareModel: plan.hardwareModel || '',
                hardwareVendor: plan.hardwareVendor || '',

                energyEfficiency: {
                    joulesPerTH: Number(plan.joulesPerTH) || 15.0,
                    label: `${(Number(plan.joulesPerTH) || 15.0).toFixed(1)} J/TH`
                },
                joulesPerTH: Number(plan.joulesPerTH) || 15.0,

                electricityRate: {
                    baseUSDPerKWh: rates.rateBaseUSDPerKWh,
                    demandUSDPerKWh: rates.rateDemandUSDPerKWh,
                    allInUSDPerKWh: rates.rateAllInUSDPerKWh,
                    display: `$${rates.rateAllInUSDPerKWh.toFixed(3)}/kWh`
                },
                wallPowerDerating: rates.wallPowerDerating,

                minAmount: plan.minAmount,
                maxAmount: plan.maxAmount,
                minAmountMoney: buildMoney(plan.minAmount / btcPrice, plan.minAmount),
                maxAmountMoney: buildMoney(plan.maxAmount / btcPrice, plan.maxAmount),
                minAmountBTC: parseFloat((plan.minAmount / btcPrice).toFixed(8)),
                maxAmountBTC: parseFloat((plan.maxAmount / btcPrice).toFixed(8)),
                costPerTH: costData
            };
        });

        // ------------------------------------------------------------------
        // 9. RESULT CONTAINER
        // ------------------------------------------------------------------
        let result = {
            calculationType: calcType,
            timestamp: new Date().toISOString(),
            success: true,
            btcPriceUSD: parseFloat(btcPrice.toFixed(2)),
            btcPriceFormatted: formatUSD(btcPrice),
            btcLogoUrl,
            electricityContext: {
                rateBaseUSDPerKWh: globalRates.rateBaseUSDPerKWh,
                rateDemandUSDPerKWh: globalRates.rateDemandUSDPerKWh,
                rateAllInUSDPerKWh: globalRates.rateAllInUSDPerKWh,
                wallPowerDerating: globalRates.wallPowerDerating
            }
        };

        // ------------------------------------------------------------------
        // 10. CALC TYPE: single_cycle
        // ------------------------------------------------------------------
        if (calcType === 'single_cycle') {
            if (hasHashrate) {
                const requestedTH = parseFloat(hashrateTH);

                const hashrateOptions = plans.map(plan => {
                    const feePercent = resolveCycleFeePercent(plan);
                    const feeDecimal = feePercent / 100;
                    const rates = resolvePlanRates(plan);

                    const btcMinedPerTH = BTC_PER_TH_PER_HOUR * plan.duration;
                    const btcReturnNeeded = requestedTH * btcMinedPerTH;
                    const usdReturnNeeded = btcReturnNeeded * btcPrice;
                    const netPrincipalNeeded = usdReturnNeeded / (plan.percentage / 100);
                    const grossInvestment = netPrincipalNeeded / (1 - feeDecimal);

                    const isWithinRange = grossInvestment >= plan.minAmount && grossInvestment <= plan.maxAmount;
                    const effectiveInvestment = Math.max(grossInvestment, plan.minAmount);

                    const effectiveFee = effectiveInvestment * feeDecimal;
                    const effectiveNet = effectiveInvestment - effectiveFee;
                    const effectiveHashpower = calculateHashpower(
                        effectiveNet, plan.percentage, plan.duration, btcPrice
                    );

                    const projection = calculateSingleCycleProjection(effectiveInvestment, plan, btcPrice);

                    return {
                        planId: plan._id.toString(),
                        planName: plan.name,

                        hardwareModel: plan.hardwareModel || '',
                        hardwareVendor: plan.hardwareVendor || '',
                        energyEfficiency: projection.energyEfficiency,
                        powerCostPerCycle: projection.powerCostPerCycle,
                        electricityRate: projection.electricityRate,
                        electricityFee: projection.electricityFee,
                        electricity: projection.electricity,
                        joulesPerTH: projection.energyEfficiency.joulesPerTH,
                        wallPowerDerating: rates.wallPowerDerating,

                        requestedTH,
                        requiredInvestment: buildMoney(grossInvestment / btcPrice, grossInvestment),
                        effectiveInvestment: buildMoney(effectiveInvestment / btcPrice, effectiveInvestment),
                        effectiveHashpower,
                        costPerTH: effectiveHashpower > 0
                            ? buildMoney((effectiveInvestment / effectiveHashpower) / btcPrice,
                                         effectiveInvestment / effectiveHashpower)
                            : buildMoney(0, 0),
                        costPerTHUSD: effectiveHashpower > 0
                            ? parseFloat((effectiveInvestment / effectiveHashpower).toFixed(2)) : 0,
                        costPerTHBTC: effectiveHashpower > 0
                            ? parseFloat((effectiveInvestment / effectiveHashpower / btcPrice).toFixed(8)) : 0,
                        isWithinRange,
                        rangeStatus: grossInvestment < plan.minAmount ? 'below_minimum'
                            : grossInvestment > plan.maxAmount ? 'above_maximum'
                            : 'within_range',
                        minAmount: plan.minAmount,
                        maxAmount: plan.maxAmount,
                        planDurationHours: plan.duration,
                        durationHours: plan.duration,
                        planPercentage: plan.percentage,
                        recommendedDuration: buildRecommendedDuration(plan, 0),
                        projection
                    };
                });

                hashrateOptions.sort((a, b) => a.costPerTHUSD - b.costPerTHUSD);
                const bestOption = hashrateOptions.find(o => o.isWithinRange) || hashrateOptions[0];

                result.singleCycleCalculation = {
                    requestedTH,
                    options: hashrateOptions,
                    recommendedPlan: bestOption ? {
                        principal: bestOption.effectiveInvestment,

                        planId: bestOption.planId,
                        planName: bestOption.planName,
                        investment: bestOption.effectiveInvestment,

                        hardwareModel: bestOption.hardwareModel,
                        hardwareVendor: bestOption.hardwareVendor,
                        energyEfficiency: bestOption.energyEfficiency,
                        powerCostPerCycle: bestOption.powerCostPerCycle,
                        electricityRate: bestOption.electricityRate,
                        electricityFee: bestOption.electricityFee,
                        electricity: bestOption.electricity,
                        joulesPerTH: bestOption.energyEfficiency.joulesPerTH,
                        wallPowerDerating: bestOption.wallPowerDerating,

                        durationHours: bestOption.projection.durationHours,
                        planDurationHours: bestOption.projection.durationHours,
                        cycleDurationHours: bestOption.projection.durationHours,
                        planDurationDays: bestOption.projection.planDurationDays,

                        hashpower: bestOption.effectiveHashpower,
                        costPerTH: bestOption.costPerTH,
                        totalPayout: bestOption.projection.totalPayout,
                        totalProfit: bestOption.projection.totalProfit,
                        totalReturn: bestOption.projection.totalReturn,
                        monthlyNetPayout: bestOption.projection.monthlyNetPayout,
                        netAfterPower: bestOption.projection.netAfterPower,
                        roiPercent: bestOption.projection.roiPercent,
                        cycleFeePercent: bestOption.projection.cycleFeePercent,
                        recommendedDuration: bestOption.recommendedDuration,
                        monthlyBreakdown: [],
                        payoutPerMonth: bestOption.projection.payoutPerMonth,
                        reason: `Best cost efficiency at ${bestOption.costPerTH.display}/TH/s`
                    } : null
                };
            }
            else {
                const amount = parseFloat(investmentAmount);

                const projections = plans.map(plan => {
                    const projection = calculateSingleCycleProjection(amount, plan, btcPrice);

                    return {
                        planId: plan._id.toString(),
                        planName: plan.name,
                        planDescription: plan.description,
                        planBadge: plan.badge,
                        planTier: plan.tier,
                        planPercentage: plan.percentage,

                        hardwareModel: plan.hardwareModel || '',
                        hardwareVendor: plan.hardwareVendor || '',
                        energyEfficiency: projection.energyEfficiency,
                        powerCostPerCycle: projection.powerCostPerCycle,
                        electricityRate: projection.electricityRate,
                        electricityFee: projection.electricityFee,
                        electricity: projection.electricity,
                        joulesPerTH: projection.energyEfficiency.joulesPerTH,
                        wallPowerDerating: projection.electricity.wallPowerDerating,

                        durationHours: plan.duration,
                        planDurationHours: plan.duration,
                        cycleDurationHours: plan.duration,
                        planDurationDays: parseFloat((plan.duration / 24).toFixed(2)),

                        isEligible: amount >= plan.minAmount && amount <= plan.maxAmount,
                        minAmount: plan.minAmount,
                        maxAmount: plan.maxAmount,
                        recommendedDuration: buildRecommendedDuration(plan, 0),
                        ...projection
                    };
                });

                projections.sort((a, b) => b.netAfterPowerUSD - a.netAfterPowerUSD);
                const eligibleSorted = projections.filter(p => p.isEligible);
                const bestPlan = eligibleSorted[0] || projections[0];

                result.singleCycleCalculation = {
                    investment: buildMoney(amount / btcPrice, amount),
                    investmentUSD: amount,
                    investmentBTC: parseFloat((amount / btcPrice).toFixed(8)),
                    eligiblePlansCount: eligibleSorted.length,
                    projections,
                    recommendedPlan: {
                        principal: buildMoney(amount / btcPrice, amount),

                        planId: bestPlan.planId,
                        planName: bestPlan.planName,
                        planDescription: bestPlan.planDescription,
                        planBadge: bestPlan.planBadge,
                        planTier: bestPlan.planTier,
                        planPercentage: bestPlan.planPercentage,

                        hardwareModel: bestPlan.hardwareModel,
                        hardwareVendor: bestPlan.hardwareVendor,
                        energyEfficiency: bestPlan.energyEfficiency,
                        powerCostPerCycle: bestPlan.powerCostPerCycle,
                        electricityRate: bestPlan.electricityRate,
                        electricityFee: bestPlan.electricityFee,
                        electricity: bestPlan.electricity,
                        joulesPerTH: bestPlan.energyEfficiency.joulesPerTH,
                        wallPowerDerating: bestPlan.electricity.wallPowerDerating,

                        durationHours: bestPlan.durationHours,
                        planDurationHours: bestPlan.durationHours,
                        cycleDurationHours: bestPlan.durationHours,
                        planDurationDays: bestPlan.planDurationDays,

                        cycleFeePercent: bestPlan.cycleFeePercent,
                        investment: buildMoney(amount / btcPrice, amount),
                        hashpower: bestPlan.hashpower,
                        totalPayout: bestPlan.totalPayout,
                        totalProfit: bestPlan.totalProfit,
                        totalReturn: bestPlan.totalReturn,
                        monthlyNetPayout: bestPlan.monthlyNetPayout,
                        netAfterPower: bestPlan.netAfterPower,
                        roiPercent: bestPlan.roiPercent,
                        totalFees: bestPlan.totalFees,
                        recommendedDuration: bestPlan.recommendedDuration,
                        monthlyBreakdown: [],
                        payoutPerMonth: bestPlan.payoutPerMonth,
                        reason: `Best net profit after power: ${bestPlan.netAfterPower.display} (${bestPlan.roiPercent}% ROI over ${bestPlan.durationHours}h)`
                    }
                };
            }
        }

        // ------------------------------------------------------------------
        // 11. CALC TYPE: hashrate
        // ------------------------------------------------------------------
        else if (calcType === 'hashrate' && hasHashrate) {
            const requestedTH = parseFloat(hashrateTH);
            const monthsToUse = parsedDurationMonths;

            const hashrateOptions = planMetrics.map(plan => {
                const sourcePlan = plans.find(p => p._id.toString() === plan.planId);
                const feePercent = resolveCycleFeePercent(sourcePlan);
                const feeDecimal = feePercent / 100;
                const rates = resolvePlanRates(sourcePlan);

                const btcMinedPerTH = BTC_PER_TH_PER_HOUR * plan.durationHours;
                const btcReturnNeeded = requestedTH * btcMinedPerTH;
                const usdReturnNeeded = btcReturnNeeded * btcPrice;
                const netPrincipalNeeded = usdReturnNeeded / (plan.percentage / 100);
                const grossInvestment = netPrincipalNeeded / (1 - feeDecimal);

                const isWithinRange = grossInvestment >= plan.minAmount && grossInvestment <= plan.maxAmount;
                const effectiveInvestment = Math.max(grossInvestment, plan.minAmount);
                const effectiveFee = effectiveInvestment * feeDecimal;
                const effectiveNet = effectiveInvestment - effectiveFee;
                const effectiveHashpower = calculateHashpower(
                    effectiveNet, plan.percentage, plan.durationHours, btcPrice
                );

                const projection = calculateContractProjection(
                    effectiveInvestment, sourcePlan, monthsToUse, btcPrice
                );

                return {
                    planId: plan.planId,
                    planName: plan.name,

                    hardwareModel: plan.hardwareModel,
                    hardwareVendor: plan.hardwareVendor,
                    energyEfficiency: projection.energyEfficiency,
                    powerCostPerCycle: projection.powerCostPerCycle,
                    electricityRate: projection.electricityRate,
                    electricityFee: projection.electricityFee,
                    electricity: projection.electricity,
                    joulesPerTH: projection.energyEfficiency.joulesPerTH,
                    wallPowerDerating: rates.wallPowerDerating,

                    requestedTH,
                    requiredInvestment: buildMoney(grossInvestment / btcPrice, grossInvestment),
                    effectiveInvestment: buildMoney(effectiveInvestment / btcPrice, effectiveInvestment),
                    effectiveHashpower,
                    hashpowerPerDollar: effectiveHashpower > 0
                        ? parseFloat((effectiveHashpower / effectiveInvestment).toFixed(6)) : 0,
                    costPerTH: effectiveHashpower > 0
                        ? buildMoney((effectiveInvestment / effectiveHashpower) / btcPrice,
                                     effectiveInvestment / effectiveHashpower)
                        : buildMoney(0, 0),
                    costPerTHUSD: effectiveHashpower > 0
                        ? parseFloat((effectiveInvestment / effectiveHashpower).toFixed(2)) : 0,
                    costPerTHBTC: effectiveHashpower > 0
                        ? parseFloat((effectiveInvestment / effectiveHashpower / btcPrice).toFixed(8)) : 0,
                    isWithinRange,
                    rangeStatus: grossInvestment < plan.minAmount ? 'below_minimum'
                        : grossInvestment > plan.maxAmount ? 'above_maximum'
                        : 'within_range',
                    minAmount: plan.minAmount,
                    maxAmount: plan.maxAmount,
                    planDurationHours: plan.durationHours,
                    durationHours: plan.durationHours,
                    planPercentage: plan.percentage,
                    recommendedDuration: buildRecommendedDuration(sourcePlan, monthsToUse),
                    projection
                };
            });

            hashrateOptions.sort((a, b) => a.costPerTHUSD - b.costPerTHUSD);
            const bestOption = hashrateOptions.find(o => o.isWithinRange) || hashrateOptions[0];

            result.hashrateCalculation = {
                requestedTH,
                options: hashrateOptions,
                recommendedPlan: bestOption ? {
                    principal: bestOption.effectiveInvestment,

                    planId: bestOption.planId,
                    planName: bestOption.planName,
                    investment: bestOption.effectiveInvestment,
                    hashpower: bestOption.effectiveHashpower,
                    costPerTH: bestOption.costPerTH,

                    hardwareModel: bestOption.hardwareModel,
                    hardwareVendor: bestOption.hardwareVendor,
                    energyEfficiency: bestOption.energyEfficiency,
                    powerCostPerCycle: bestOption.powerCostPerCycle,
                    electricityRate: bestOption.electricityRate,
                    electricityFee: bestOption.electricityFee,
                    electricity: bestOption.electricity,
                    joulesPerTH: bestOption.energyEfficiency.joulesPerTH,
                    wallPowerDerating: bestOption.wallPowerDerating,

                    recommendedDuration: bestOption.recommendedDuration,
                    projection: bestOption.projection,
                    monthlyBreakdown: bestOption.projection.monthlyBreakdown,
                    payoutPerMonth: bestOption.projection.payoutPerMonth,
                    totalReturn: bestOption.projection.totalReturn,
                    totalProfit: bestOption.projection.totalProfit,
                    netAfterPower: bestOption.projection.netAfterPower,
                    monthlyNetPayout: bestOption.projection.monthlyNetPayout,
                    roiPercent: bestOption.projection.roiPercent,
                    totalFees: bestOption.projection.totalFees,
                    cyclesPerMonth: bestOption.projection.cyclesPerMonth,
                    cycleFeePercent: bestOption.projection.cycleFeePercent,
                    durationHours: bestOption.projection.durationHours,
                    planDurationHours: bestOption.projection.durationHours,
                    reason: `Best cost efficiency at ${bestOption.costPerTH.display}/TH/s`
                } : null
            };
        }

        // ------------------------------------------------------------------
        // 12. CALC TYPE: investment
        // ------------------------------------------------------------------
        else if (calcType === 'investment' && hasAmount) {
            const amount = parseFloat(investmentAmount);
            const monthsToUse = parsedDurationMonths;

            const eligiblePlans = plans.filter(plan =>
                amount >= plan.minAmount && amount <= plan.maxAmount
            );

            if (eligiblePlans.length === 0) {
                const plansByRange = [...plans].sort((a, b) => {
                    const aDist = Math.min(Math.abs(amount - a.minAmount), Math.abs(amount - a.maxAmount));
                    const bDist = Math.min(Math.abs(amount - b.minAmount), Math.abs(amount - b.maxAmount));
                    return aDist - bDist;
                });

                const closestPlan = plansByRange[0];
                const isBelowMin = amount < closestPlan.minAmount;

                result.investmentCalculation = {
                    investment: buildMoney(amount / btcPrice, amount),
                    investmentUSD: amount,
                    investmentBTC: parseFloat((amount / btcPrice).toFixed(8)),
                    eligiblePlans: [],
                    recommendation: {
                        type: isBelowMin ? 'increase_investment' : 'reduce_investment',
                        message: isBelowMin
                            ? `Minimum investment for ${closestPlan.name} is ${formatUSD(closestPlan.minAmount)}. You need ${formatUSD(closestPlan.minAmount - amount)} more.`
                            : `Maximum investment for ${closestPlan.name} is ${formatUSD(closestPlan.maxAmount)}. Consider reducing by ${formatUSD(amount - closestPlan.maxAmount)}.`,
                        closestPlan: {
                            planId: closestPlan._id.toString(),
                            planName: closestPlan.name,
                            minAmount: closestPlan.minAmount,
                            maxAmount: closestPlan.maxAmount,
                            requiredAdjustment: isBelowMin ? closestPlan.minAmount - amount : -(amount - closestPlan.maxAmount)
                        }
                    }
                };
            } else {
                const planProjections = eligiblePlans.map(plan => {
                    const projection = calculateContractProjection(amount, plan, monthsToUse, btcPrice);

                    return {
                        planId: plan._id.toString(),
                        planName: plan.name,
                        planDescription: plan.description,
                        planBadge: plan.badge,
                        planTier: plan.tier,
                        planPercentage: plan.percentage,
                        planDurationHours: plan.duration,
                        durationHours: plan.duration,
                        planDurationDays: parseFloat((plan.duration / 24).toFixed(2)),
                        cyclesPerMonth: calculateCyclesPerMonth(plan.duration),

                        hardwareModel: plan.hardwareModel || '',
                        hardwareVendor: plan.hardwareVendor || '',
                        energyEfficiency: projection.energyEfficiency,
                        powerCostPerCycle: projection.powerCostPerCycle,
                        electricityRate: projection.electricityRate,
                        electricityFee: projection.electricityFee,
                        electricity: projection.electricity,
                        joulesPerTH: projection.energyEfficiency.joulesPerTH,
                        wallPowerDerating: projection.electricity.wallPowerDerating,

                        recommendedDuration: buildRecommendedDuration(plan, monthsToUse),
                        ...projection
                    };
                });

                planProjections.sort((a, b) => b.netAfterPowerUSD - a.netAfterPowerUSD);
                const bestPlan = planProjections[0];

                result.investmentCalculation = {
                    investment: buildMoney(amount / btcPrice, amount),
                    investmentUSD: amount,
                    investmentBTC: parseFloat((amount / btcPrice).toFixed(8)),
                    eligiblePlansCount: eligiblePlans.length,
                    projections: planProjections,
                    recommendedPlan: {
                        planId: bestPlan.planId,
                        planName: bestPlan.planName,
                        planDescription: bestPlan.planDescription,
                        planBadge: bestPlan.planBadge,
                        planTier: bestPlan.planTier,
                        planPercentage: bestPlan.planPercentage,

                        hardwareModel: bestPlan.hardwareModel,
                        hardwareVendor: bestPlan.hardwareVendor,
                        energyEfficiency: bestPlan.energyEfficiency,
                        powerCostPerCycle: bestPlan.powerCostPerCycle,
                        electricityRate: bestPlan.electricityRate,
                        electricityFee: bestPlan.electricityFee,
                        electricity: bestPlan.electricity,
                        joulesPerTH: bestPlan.energyEfficiency.joulesPerTH,
                        wallPowerDerating: bestPlan.electricity.wallPowerDerating,

                        durationHours: bestPlan.durationHours,
                        planDurationHours: bestPlan.durationHours,
                        cycleDurationHours: bestPlan.durationHours,
                        planDurationDays: bestPlan.planDurationDays,
                        cyclesPerMonth: bestPlan.cyclesPerMonth,
                        totalCycles: bestPlan.totalCycles,
                        totalMonths: bestPlan.totalMonths,

                        cycleFeePercent: bestPlan.cycleFeePercent,
                        recommendedDuration: bestPlan.recommendedDuration,

                        principal: buildMoney(amount / btcPrice, amount),

                        netPrincipal: bestPlan.netPrincipal,
                        firstCycleFee: bestPlan.firstCycleFee,
                        totalFees: bestPlan.totalFees,
                        hashpower: bestPlan.hashpower,
                        totalReturn: bestPlan.totalReturn,
                        totalPayout: bestPlan.totalPayout,
                        totalProfit: bestPlan.totalProfit,
                        netAfterPower: bestPlan.netAfterPower,
                        monthlyNetPayout: bestPlan.monthlyNetPayout,
                        finalPayout: bestPlan.finalPayout,
                        netMonthlyPayout: bestPlan.netMonthlyPayout,

                        principalUSD: bestPlan.principalUSD,
                        principalBTC: bestPlan.principalBTC,
                        netPrincipalUSD: bestPlan.netPrincipalUSD,
                        netPrincipalBTC: bestPlan.netPrincipalBTC,
                        totalReturnUSD: bestPlan.totalReturnUSD,
                        totalReturnBTC: bestPlan.totalReturnBTC,
                        totalPayoutUSD: bestPlan.totalPayoutUSD,
                        totalPayoutBTC: bestPlan.totalPayoutBTC,
                        totalProfitUSD: bestPlan.totalProfitUSD,
                        totalProfitBTC: bestPlan.totalProfitBTC,
                        netAfterPowerUSD: bestPlan.netAfterPowerUSD,
                        netAfterPowerBTC: bestPlan.netAfterPowerBTC,
                        monthlyNetPayoutUSD: bestPlan.monthlyNetPayoutUSD,
                        monthlyNetPayoutBTC: bestPlan.monthlyNetPayoutBTC,
                        finalPayoutUSD: bestPlan.finalPayoutUSD,
                        finalPayoutBTC: bestPlan.finalPayoutBTC,
                        totalFeesUSD: bestPlan.totalFeesUSD,
                        totalFeesBTC: bestPlan.totalFeesBTC,
                        roiPercent: bestPlan.roiPercent,
                        roiPerMonth: bestPlan.roiPerMonth,

                        monthlyBreakdown: bestPlan.monthlyBreakdown,
                        payoutPerMonth: bestPlan.payoutPerMonth,

                        reason: `Highest net after power: ${bestPlan.netAfterPower.display} (${bestPlan.roiPercent}% ROI) over ${bestPlan.durationMonths} month(s)`
                    }
                };
            }
        }

        // ------------------------------------------------------------------
        // 13. CALC TYPE: duration
        // ------------------------------------------------------------------
        else if (calcType === 'duration' && parsedDurationMonths > 0) {
            const months = parsedDurationMonths;

            const durationOptions = planMetrics.map(plan => {
                const sourcePlan = plans.find(p => p._id.toString() === plan.planId);
                const projection = calculateContractProjection(plan.minAmount, sourcePlan, months, btcPrice);

                return {
                    planId: plan.planId,
                    planName: plan.name,
                    planDescription: plan.description,
                    planBadge: sourcePlan.badge,
                    planTier: sourcePlan.tier,
                    planPercentage: plan.percentage,
                    planDurationHours: plan.durationHours,
                    durationHours: plan.durationHours,
                    planDurationDays: plan.durationDays,
                    cyclesPerMonth: plan.cyclesPerMonth,

                    hardwareModel: plan.hardwareModel,
                    hardwareVendor: plan.hardwareVendor,
                    energyEfficiency: projection.energyEfficiency,
                    powerCostPerCycle: projection.powerCostPerCycle,
                    electricityRate: projection.electricityRate,
                    electricityFee: projection.electricityFee,
                    electricity: projection.electricity,
                    joulesPerTH: projection.energyEfficiency.joulesPerTH,
                    wallPowerDerating: projection.electricity.wallPowerDerating,

                    minInvestment: buildMoney(plan.minAmount / btcPrice, plan.minAmount),
                    recommendedDuration: buildRecommendedDuration(sourcePlan, months),
                    ...projection
                };
            });

            durationOptions.sort((a, b) => b.roiPerMonth - a.roiPerMonth);
            const bestPlan = durationOptions[0];

            result.durationCalculation = {
                durationMonths: months,
                options: durationOptions,
                recommendedPlan: {
                    principal: bestPlan.principal,

                    planId: bestPlan.planId,
                    planName: bestPlan.planName,
                    planPercentage: bestPlan.planPercentage,

                    hardwareModel: bestPlan.hardwareModel,
                    hardwareVendor: bestPlan.hardwareVendor,
                    energyEfficiency: bestPlan.energyEfficiency,
                    powerCostPerCycle: bestPlan.powerCostPerCycle,
                    electricityRate: bestPlan.electricityRate,
                    electricityFee: bestPlan.electricityFee,
                    electricity: bestPlan.electricity,
                    joulesPerTH: bestPlan.energyEfficiency.joulesPerTH,
                    wallPowerDerating: bestPlan.electricity.wallPowerDerating,

                    durationHours: bestPlan.durationHours,
                    planDurationHours: bestPlan.durationHours,
                    cycleDurationHours: bestPlan.durationHours,

                    cyclesPerMonth: bestPlan.cyclesPerMonth,
                    cycleFeePercent: bestPlan.cycleFeePercent,
                    minInvestment: bestPlan.minInvestment,
                    hashpower: bestPlan.hashpower,
                    totalPayout: bestPlan.totalPayout,
                    totalProfit: bestPlan.totalProfit,
                    totalReturn: bestPlan.totalReturn,
                    netAfterPower: bestPlan.netAfterPower,
                    monthlyNetPayout: bestPlan.monthlyNetPayout,
                    roiPercent: bestPlan.roiPercent,
                    roiPerMonth: bestPlan.roiPerMonth,
                    totalFees: bestPlan.totalFees,
                    totalMonths: bestPlan.totalMonths,
                    totalCycles: bestPlan.totalCycles,
                    recommendedDuration: bestPlan.recommendedDuration,

                    monthlyBreakdown: bestPlan.monthlyBreakdown,
                    payoutPerMonth: bestPlan.payoutPerMonth,

                    reason: `Best ROI per month after power: ${bestPlan.roiPerMonth}% (${bestPlan.roiPercent}% total over ${months} month(s))`
                }
            };
        }

        // ------------------------------------------------------------------
        // 14. FALLBACK: overview
        // ------------------------------------------------------------------
        else {
            const planComparisons = planMetrics.map(plan => {
                const sourcePlan = plans.find(p => p._id.toString() === plan.planId);
                const projection = calculateContractProjection(plan.minAmount, sourcePlan, 1, btcPrice);

                return {
                    planId: plan.planId,
                    planName: plan.name,
                    planDescription: plan.description,
                    planBadge: sourcePlan.badge,
                    planTier: sourcePlan.tier,
                    planPercentage: plan.percentage,
                    planDurationHours: plan.durationHours,
                    durationHours: plan.durationHours,
                    planDurationDays: plan.durationDays,
                    cyclesPerMonth: plan.cyclesPerMonth,

                    hardwareModel: plan.hardwareModel,
                    hardwareVendor: plan.hardwareVendor,
                    energyEfficiency: projection.energyEfficiency,
                    powerCostPerCycle: projection.powerCostPerCycle,
                    electricityRate: projection.electricityRate,
                    electricityFee: projection.electricityFee,
                    electricity: projection.electricity,
                    joulesPerTH: projection.energyEfficiency.joulesPerTH,
                    wallPowerDerating: projection.electricity.wallPowerDerating,

                    minAmount: plan.minAmount,
                    maxAmount: plan.maxAmount,
                    minAmountMoney: plan.minAmountMoney,
                    maxAmountMoney: plan.maxAmountMoney,
                    costPerTH: plan.costPerTH,
                    recommendedDuration: buildRecommendedDuration(sourcePlan, 1),
                    minInvestmentHashpower: projection.hashpower,
                    minInvestmentMonthlyProfit: projection.totalProfit,
                    minInvestmentMonthlyProfitUSD: projection.totalProfitUSD,
                    minInvestmentMonthlyNetAfterPower: projection.netAfterPower,
                    minInvestmentMonthlyNetAfterPowerUSD: projection.netAfterPowerUSD,
                    minInvestmentMonthlyROI: projection.roiPercent,
                    monthlyBreakdown: projection.monthlyBreakdown,
                    payoutPerMonth: projection.payoutPerMonth
                };
            });

            planComparisons.sort((a, b) => {
                if (!a.costPerTH || !b.costPerTH) return 0;
                return a.costPerTH.costPerTHUSD - b.costPerTH.costPerTHUSD;
            });

            const mostCostEffective = planComparisons[0];

            result.overview = {
                totalPlans: planComparisons.length,
                plans: planComparisons,
                mostCostEffectivePlan: {
                    planId: mostCostEffective.planId,
                    planName: mostCostEffective.planName,

                    hardwareModel: mostCostEffective.hardwareModel,
                    hardwareVendor: mostCostEffective.hardwareVendor,
                    energyEfficiency: mostCostEffective.energyEfficiency,
                    powerCostPerCycle: mostCostEffective.powerCostPerCycle,
                    electricityRate: mostCostEffective.electricityRate,
                    electricityFee: mostCostEffective.electricityFee,
                    electricity: mostCostEffective.electricity,
                    joulesPerTH: mostCostEffective.energyEfficiency.joulesPerTH,
                    wallPowerDerating: mostCostEffective.electricity.wallPowerDerating,

                    costPerTH: mostCostEffective.costPerTH,
                    costPerTHUSD: mostCostEffective.costPerTH.costPerTHUSD,
                    costPerTHBTC: mostCostEffective.costPerTH.costPerTHBTC,
                    minInvestment: mostCostEffective.minAmount,
                    minInvestmentMoney: mostCostEffective.minAmountMoney,
                    hashpowerAtMin: mostCostEffective.costPerTH.hashpowerAtMin,
                    durationHours: mostCostEffective.durationHours,
                    planDurationHours: mostCostEffective.durationHours,
                    recommendedDuration: mostCostEffective.recommendedDuration,
                    monthlyBreakdown: mostCostEffective.monthlyBreakdown,
                    payoutPerMonth: mostCostEffective.payoutPerMonth,
                    reason: `Lowest cost per TH/s at ${mostCostEffective.costPerTH.display}/TH/s`
                }
            };
        }

        // ==================================================================
        // 15. USER CONTEXT — CORRECTLY IDENTIFY LOGGED-IN USERS
        // ==================================================================
        // ROOT CAUSE FIX:
        //   User.findById(...).lean() returns a PLAIN OBJECT, not a Mongoose
        //   document. Mongoose Map fields (balances.main, balances.matured)
        //   are serialized by lean() to plain objects that DO NOT have a
        //   .entries() method. The previous code called
        //       dbUser.balances.main.entries()
        //   which throws "entries is not a function", gets swallowed by the
        //   surrounding try/catch, and silently downgrades the user to guest.
        //
        //   Fix: use safeEntries() which handles both a Mongoose Map AND a
        //   lean plain object.
        // ==================================================================
        let authToken = null;
        let authSource = 'none';

        // 1a. Authorization header (primary method used by index.html)
        if (req.headers && typeof req.headers.authorization === 'string') {
            const rawAuth = req.headers.authorization.trim();
            const bearerMatch = rawAuth.match(/^Bearer\s+(.+)$/i);
            if (bearerMatch && bearerMatch[1]) {
                authToken = bearerMatch[1].trim();
                authSource = 'authorization_header';
            }
        }

        // 1b. Fallback: httpOnly cookie (only if cookieParser is mounted)
        if (!authToken && req.cookies && typeof req.cookies.jwt === 'string' && req.cookies.jwt.trim()) {
            authToken = req.cookies.jwt.trim();
            authSource = 'cookie';
        }

        // Default: guest until proven otherwise
        result.userContext = { isLoggedIn: false, authSource };

        // Helper: iterate a Mongoose Map OR a lean() plain object safely
        const safeEntries = (container) => {
            if (!container) return [];
            if (container instanceof Map) return Array.from(container.entries());
            if (typeof container === 'object') return Object.entries(container);
            return [];
        };

        if (authToken) {
            try {
                const decoded = verifyJWT(authToken);

                if (!decoded || !decoded.id) {
                    console.warn(
                        `[Calculator Auth] Token present (source=${authSource}) but missing 'id' claim; treating as guest.`
                    );
                } else {
                    const dbUser = await User.findById(decoded.id)
                        .select('firstName lastName email balances')
                        .lean();

                    if (!dbUser) {
                        console.warn(
                            `[Calculator Auth] Token valid but no user found for id=${decoded.id}; treating as guest.`
                        );
                    } else {
                        // Compute real USD balances from on-chain quantities.
                        // dbUser is a lean plain object, so use safeEntries.
                        let userMainUSD = 0;
                        let userMaturedUSD = 0;

                        if (dbUser.balances) {
                            for (const [asset, balance] of safeEntries(dbUser.balances.main)) {
                                if (balance > 0 && asset !== 'usd') {
                                    const p = await getCryptoPrice(asset.toUpperCase());
                                    if (p && p > 0) userMainUSD += balance * p;
                                }
                            }
                            for (const [asset, balance] of safeEntries(dbUser.balances.matured)) {
                                if (balance > 0 && asset !== 'usd') {
                                    const p = await getCryptoPrice(asset.toUpperCase());
                                    if (p && p > 0) userMaturedUSD += balance * p;
                                }
                            }
                        }

                        const totalAvailableUSD = userMainUSD + userMaturedUSD;
                        const fullName = [dbUser.firstName, dbUser.lastName]
                            .filter(Boolean)
                            .join(' ')
                            .trim();

                        result.userContext = {
                            isLoggedIn: true,
                            authSource,
                            userId: dbUser._id,
                            email: dbUser.email || null,
                            firstName: dbUser.firstName || null,
                            lastName: dbUser.lastName || null,
                            fullName: fullName || null,
                            totalAvailable: buildMoney(totalAvailableUSD / btcPrice, totalAvailableUSD),
                            mainBalance: buildMoney(userMainUSD / btcPrice, userMainUSD),
                            maturedBalance: buildMoney(userMaturedUSD / btcPrice, userMaturedUSD),
                            totalAvailableUSD: parseFloat(totalAvailableUSD.toFixed(2)),
                            mainBalanceUSD: parseFloat(userMainUSD.toFixed(2)),
                            maturedBalanceUSD: parseFloat(userMaturedUSD.toFixed(2))
                        };

                        console.log(
                            `[Calculator Auth] Identified logged-in user: ${fullName || dbUser.email} (id=${dbUser._id}, source=${authSource})`
                        );
                    }
                }
            } catch (authErr) {
                console.warn(
                    `[Calculator Auth] Token provided (source=${authSource}) but verification failed: ${authErr.message}. Treating as guest.`
                );
                result.userContext = { isLoggedIn: false, authSource, authError: authErr.message };
            }
        } else {
            console.log('[Calculator Auth] No auth token present; treating as guest.');
        }

        // ==================================================================
        // 16. ACTIVITY LOG — attributed to the real user when logged in
        // ==================================================================
        try {
            const deviceInfo = await getUserDeviceInfo(req);

            const isLoggedIn = !!result.userContext?.isLoggedIn;

            let summary = null;
            if (calcType === 'single_cycle' && result.singleCycleCalculation) {
                summary = {
                    investmentAmount: result.singleCycleCalculation.investmentUSD || null,
                    requestedTH: result.singleCycleCalculation.requestedTH || null,
                    recommendedPlan: result.singleCycleCalculation.recommendedPlan?.planName || null,
                    netAfterPowerUSD: result.singleCycleCalculation.recommendedPlan?.netAfterPowerUSD || null,
                    electricityFeeUSD: result.singleCycleCalculation.recommendedPlan?.electricityFee?.usd || null,
                    powerCostPerCycleUSD: result.singleCycleCalculation.recommendedPlan?.powerCostPerCycle?.usd || null,
                    joulesPerTH: result.singleCycleCalculation.recommendedPlan?.energyEfficiency?.joulesPerTH || null
                };
            } else if (calcType === 'hashrate' && result.hashrateCalculation) {
                summary = {
                    requestedTH: result.hashrateCalculation.requestedTH,
                    recommendedPlan: result.hashrateCalculation.recommendedPlan?.planName || null,
                    durationMonths: parsedDurationMonths,
                    netAfterPowerUSD: result.hashrateCalculation.recommendedPlan?.netAfterPowerUSD || null,
                    electricityFeeUSD: result.hashrateCalculation.recommendedPlan?.electricityFee?.usd || null,
                    powerCostPerCycleUSD: result.hashrateCalculation.recommendedPlan?.powerCostPerCycle?.usd || null,
                    joulesPerTH: result.hashrateCalculation.recommendedPlan?.energyEfficiency?.joulesPerTH || null
                };
            } else if (calcType === 'investment' && result.investmentCalculation) {
                summary = {
                    investmentAmount: result.investmentCalculation.investmentUSD,
                    eligiblePlansCount: result.investmentCalculation.eligiblePlansCount || 0,
                    recommendedPlan: result.investmentCalculation.recommendedPlan?.planName || null,
                    durationMonths: parsedDurationMonths,
                    netAfterPowerUSD: result.investmentCalculation.recommendedPlan?.netAfterPowerUSD || null,
                    electricityFeeUSD: result.investmentCalculation.recommendedPlan?.electricityFee?.usd || null,
                    powerCostPerCycleUSD: result.investmentCalculation.recommendedPlan?.powerCostPerCycle?.usd || null,
                    joulesPerTH: result.investmentCalculation.recommendedPlan?.energyEfficiency?.joulesPerTH || null
                };
            } else if (calcType === 'duration' && result.durationCalculation) {
                summary = {
                    durationMonths: result.durationCalculation.durationMonths,
                    recommendedPlan: result.durationCalculation.recommendedPlan?.planName || null,
                    netAfterPowerUSD: result.durationCalculation.recommendedPlan?.netAfterPowerUSD || null,
                    electricityFeeUSD: result.durationCalculation.recommendedPlan?.electricityFee?.usd || null,
                    powerCostPerCycleUSD: result.durationCalculation.recommendedPlan?.powerCostPerCycle?.usd || null,
                    joulesPerTH: result.durationCalculation.recommendedPlan?.energyEfficiency?.joulesPerTH || null
                };
            } else if (result.overview) {
                summary = {
                    totalPlans: result.overview.totalPlans,
                    mostCostEffectivePlan: result.overview.mostCostEffectivePlan?.planName || null
                };
            }

            await SystemLog.create({
                action: isLoggedIn ? 'calculator_used' : 'calculator_used_guest',
                entity: 'system',
                entityId: null,
                performedBy: isLoggedIn ? result.userContext.userId : null,
                performedByModel: isLoggedIn ? 'User' : 'System',
                performedByEmail: isLoggedIn ? result.userContext.email : null,
                performedByName: isLoggedIn
                    ? (result.userContext.fullName || result.userContext.email || 'User')
                    : 'Guest User',
                status: 'success',
                ip: deviceInfo.ip,
                userAgent: req.headers['user-agent'] || 'Unknown',
                location: deviceInfo.location || 'Unknown',
                deviceType: getDeviceType(req),
                os: getOSFromUserAgent(req.headers['user-agent']),
                browser: getBrowserFromUserAgent(req.headers['user-agent']),
                countryCode: deviceInfo.locationDetails?.country_code || 'Unknown',
                city: deviceInfo.locationDetails?.city || 'Unknown',
                region: deviceInfo.locationDetails?.region || 'Unknown',
                metadata: {
                    calculationType: calcType,
                    investmentAmount: hasAmount ? parseFloat(investmentAmount) : null,
                    hashrateTH: hasHashrate ? parseFloat(hashrateTH) : null,
                    durationMonths: parsedDurationMonths,
                    btcPriceAtCalculation: btcPrice,
                    plansAvailable: plans.length,
                    electricityContext: result.electricityContext,
                    summary,
                    // Attribution diagnostics
                    authSource: result.userContext?.authSource || 'none',
                    authError: result.userContext?.authError || null,
                    processingTimeMs: Date.now() - startTime
                }
            });
        } catch (logErr) {
            console.error('Calculator activity log failed:', logErr.message);
        }

        // ==================================================================
        // 17. RESPONSE
        // ==================================================================
        const processingTime = Date.now() - startTime;

        res.status(200).json({
            status: 'success',
            success: true,
            processingTimeMs: processingTime,
            btcLogoUrl,
            data: {
                ...result,
                btcLogoUrl
            }
        });

    } catch (err) {
        console.error('Mining calculator error:', err);

        try {
            const deviceInfo = await getUserDeviceInfo(req);
            await SystemLog.create({
                action: 'calculator_error',
                entity: 'system',
                performedByModel: 'System',
                status: 'failed',
                errorMessage: err.message || 'Unknown calculator error',
                errorStack: err.stack,
                ip: deviceInfo.ip,
                userAgent: req.headers['user-agent'] || 'Unknown',
                location: deviceInfo.location || 'Unknown',
                metadata: {
                    body: req.body || {},
                    url: req.originalUrl,
                    method: req.method
                }
            });
        } catch (logErr) {
            console.error('Failed to log calculator error:', logErr.message);
        }

        res.status(500).json({
            status: 'error',
            success: false,
            message: err.message || 'An error occurred while processing your calculation.',
            processingTimeMs: Date.now() - startTime
        });
    }
});









app.post('/api/transactions/transfer', protect, [
  body('amount').isFloat({ gt: 0 }).withMessage('Amount must be greater than 0'),
  body('from').isIn(['main', 'active', 'matured', 'savings']).withMessage('Invalid source account'),
  body('to').isIn(['main', 'active', 'matured', 'savings']).withMessage('Invalid destination account')
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'fail',
      errors: errors.array()
    });
  }

  try {
    const { amount, from, to } = req.body;
    const user = await User.findById(req.user.id);

    if (user.balances[from] < amount) {
      return res.status(400).json({
        status: 'fail',
        message: `Insufficient balance in ${from} account`
      });
    }

    user.balances[from] -= amount;
    user.balances[to] += amount;
    await user.save();

    const reference = `TRF-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
    const transaction = await Transaction.create({
      user: req.user.id,
      type: 'transfer',
      amount,
      currency: 'USD',
      status: 'completed',
      method: 'internal',
      reference,
      netAmount: amount,
      details: `Transfer of $${amount} from ${from} to ${to} account`
    });

    res.status(201).json({
      status: 'success',
      data: transaction
    });

    await logActivity('transfer-funds', 'transaction', transaction._id, req.user._id, 'User', req, { amount, from, to });
  } catch (err) {
    console.error('Transfer funds error:', err);
    res.status(500).json({
      status: 'error',
      message: 'An error occurred while transferring funds'
    });
  }
});


app.get('/api/investments', protect, async (req, res) => {
  try {
    const { status, page = 1, limit = 20 } = req.query;
    const skip = (page - 1) * limit;

    const query = { user: req.user.id };
    if (status) query.status = status;

    const investments = await Investment.find(query)
      .populate('plan')
      .sort({ createdAt: -1 })
      .skip(skip)
      .limit(parseInt(limit));

    const total = await Investment.countDocuments(query);

    res.status(200).json({
      status: 'success',
      data: {
        investments,
        total,
        page: parseInt(page),
        pages: Math.ceil(total / limit)
      }
    });
  } catch (err) {
    console.error('Get investments error:', err);
    res.status(500).json({
      status: 'error',
      message: 'An error occurred while fetching investments'
    });
  }
});

app.post('/api/savings', protect, [
  body('amount').isFloat({ gt: 0 }).withMessage('Amount must be greater than 0')
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'fail',
      errors: errors.array()
    });
  }

  try {
    const { amount } = req.body;
    const user = await User.findById(req.user.id);

    if (user.balances.main < amount) {
      return res.status(400).json({
        status: 'fail',
        message: 'Insufficient balance for savings'
      });
    }

    user.balances.main -= amount;
    user.balances.savings += amount;
    await user.save();

    const reference = `SAV-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
    const transaction = await Transaction.create({
      user: req.user.id,
      type: 'transfer',
      amount,
      currency: 'USD',
      status: 'completed',
      method: 'internal',
      reference,
      netAmount: amount,
      details: `Transferred $${amount} to savings account`
    });

    res.status(201).json({
      status: 'success',
      data: transaction
    });

    await logActivity('create-savings', 'transaction', transaction._id, req.user._id, 'User', req, { amount });
  } catch (err) {
    console.error('Create savings error:', err);
    res.status(500).json({
      status: 'error',
      message: 'An error occurred while creating savings'
    });
  }
});

app.post('/api/loans', protect, [
  body('amount').isFloat({ gt: 0 }).withMessage('Amount must be greater than 0'),
  body('collateralAmount').isFloat({ gt: 0 }).withMessage('Collateral amount must be greater than 0'),
  body('duration').isInt({ gt: 0 }).withMessage('Duration must be greater than 0')
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'fail',
      errors: errors.array()
    });
  }

  try {
    const { amount, collateralAmount, duration } = req.body;
    const interestRate = 10; // Fixed interest rate for loans

    const loan = await Loan.create({
      user: req.user.id,
      amount,
      interestRate,
      duration,
      collateralAmount,
      collateralCurrency: 'BTC',
      status: 'pending'
    });

    res.status(201).json({
      status: 'success',
      data: loan
    });

    await logActivity('request-loan', 'loan', loan._id, req.user._id, 'User', req, { amount, collateralAmount, duration });
  } catch (err) {
    console.error('Request loan error:', err);
    res.status(500).json({
      status: 'error',
      message: 'An error occurred while requesting loan'
    });
  }
});

