app.post('/api/auth/send-otp', [
  body('email').isEmail().withMessage('Please provide a valid email')
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'fail',
      message: 'Please provide a valid email address'
    });
  }

  try {
    const { email } = req.body;

    const originalEmail = email;

    const user = await User.findOne({ email: originalEmail });
    if (!user) {
      return res.status(404).json({
        status: 'fail',
        message: 'User not found'
      });
    }

    const recentOtp = await OTP.findOne({
      email: originalEmail,
      createdAt: { $gte: new Date(Date.now() - 60 * 1000) } // Last 60 seconds
    });

    if (recentOtp) {
      return res.status(429).json({
        status: 'fail',
        message: 'Please wait before requesting a new OTP'
      });
    }

    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    const expiresAt = new Date(Date.now() + 5 * 60 * 1000); // 5 minutes

    await OTP.deleteMany({ email: originalEmail, used: false });

    await OTP.create({
      email: originalEmail,
      otp,
      type: 'login',
      expiresAt,
      ipAddress: req.ip,
      userAgent: req.headers['user-agent']
    });

    await sendProfessionalEmail({
      email: originalEmail,
      template: 'otp',
      data: {
        name: user.firstName,
        otp: otp,
        action: 'login'
      }
    });

    res.status(200).json({
      status: 'success',
      message: 'OTP sent successfully to your email'
    });

    await logActivity('otp_sent', 'otp', null, user._id, 'User', req, {
      email: originalEmail,
      type: 'login'
    });

  } catch (err) {
    console.error('Send OTP error:', err);
    res.status(500).json({
      status: 'error',
      message: 'Failed to send OTP. Please try again.'
    });
  }
});














