app.post('/api/admin/promos/:id/disable', adminProtect, restrictTo('super', 'finance'), async (req, res) => {
    try {
        const { id } = req.params;

        console.log(`[PROMO DISABLE] Disabling promo: ${id}`);

        if (!mongoose.Types.ObjectId.isValid(id)) {
            return res.status(400).json({
                status: 'fail',
                message: 'Invalid promo ID format'
            });
        }

        const promo = await Promo.findById(id);

        if (!promo) {
            return res.status(404).json({
                status: 'fail',
                message: 'Promo code not found'
            });
        }

        const now = new Date();
        const usedCount = await RedeemedPromo.countDocuments({ promoId: promo._id });
        const isExpired = new Date(promo.expiresAt) <= now;
        const isExhausted = usedCount >= promo.maxUses;

        if (isExpired) {
            return res.status(400).json({
                status: 'fail',
                message: 'Cannot disable an expired promo code'
            });
        }

        if (isExhausted) {
            return res.status(400).json({
                status: 'fail',
                message: 'Cannot disable an exhausted promo code'
            });
        }

        promo.isActive = false;
        promo.maxUses = usedCount; // Set maxUses to current used count to mark as exhausted
        await promo.save();

        console.log(`[PROMO DISABLE] Promo disabled: ${promo.code}`);

        await SystemLog.create({
            action: 'promo_disabled',
            entity: 'Promo',
            entityId: promo._id,
            performedBy: req.admin._id,
            performedByModel: 'Admin',
            performedByEmail: req.admin.email,
            performedByName: req.admin.name,
            status: 'success',
            metadata: {
                promoCode: promo.code,
                usedCount: usedCount,
                maxUses: promo.maxUses
            }
        });

        res.status(200).json({
            status: 'success',
            message: `Promo code "${promo.code}" disabled successfully`,
            data: {
                promo: {
                    _id: promo._id,
                    code: promo.code,
                    status: 'disabled'
                }
            }
        });

    } catch (err) {
        console.error('[PROMO DISABLE] Error:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to disable promo code'
        });
    }
});

app.post('/api/admin/promos/:id/duplicate', adminProtect, restrictTo('super', 'finance'), async (req, res) => {
    try {
        const { id } = req.params;

        console.log(`[PROMO DUPLICATE] Duplicating promo: ${id}`);

        if (!mongoose.Types.ObjectId.isValid(id)) {
            return res.status(400).json({
                status: 'fail',
                message: 'Invalid promo ID format'
            });
        }

        const originalPromo = await Promo.findById(id).lean();

        if (!originalPromo) {
            return res.status(404).json({
                status: 'fail',
                message: 'Promo code not found'
            });
        }

        const generateCode = () => {
            const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
            let code = '';
            for (let i = 0; i < 6; i++) {
                code += chars.charAt(Math.floor(Math.random() * chars.length));
            }
            return code;
        };

        let newCode = generateCode();
        let attempts = 0;
        const maxAttempts = 50;

        while (attempts < maxAttempts) {
            const existing = await Promo.findOne({ code: newCode });
            if (!existing) break;
            newCode = generateCode();
            attempts++;
        }

        if (attempts >= maxAttempts) {
            return res.status(500).json({
                status: 'error',
                message: 'Failed to generate a unique promo code. Please try again.'
            });
        }

        const duplicateData = {
            code: newCode,
            description: `${originalPromo.description} (Copy)`,
            rewardType: originalPromo.rewardType,
            rewardValue: originalPromo.rewardValue,
            rewardAsset: originalPromo.rewardAsset || 'usd',
            maxUses: originalPromo.maxUses,
            usedCount: 0,
            expiresAt: originalPromo.expiresAt,
            isActive: false, // Duplicate starts as draft
            createdBy: req.admin._id,
            targetType: originalPromo.targetType || 'all',
            userIds: originalPromo.userIds || [],
            walletType: originalPromo.walletType || 'main',
            maxRedemptionsPerUser: originalPromo.maxRedemptionsPerUser || 1,
            category: originalPromo.category || 'deposit'
        };

        const duplicatedPromo = await Promo.create(duplicateData);

        console.log(`[PROMO DUPLICATE] Promo duplicated: ${originalPromo.code} -> ${duplicatedPromo.code}`);

        await SystemLog.create({
            action: 'promo_duplicated',
            entity: 'Promo',
            entityId: duplicatedPromo._id,
            performedBy: req.admin._id,
            performedByModel: 'Admin',
            performedByEmail: req.admin.email,
            performedByName: req.admin.name,
            status: 'success',
            metadata: {
                originalCode: originalPromo.code,
                newCode: duplicatedPromo.code,
                originalId: originalPromo._id
            }
        });

        res.status(200).json({
            status: 'success',
            message: `Promo code duplicated successfully. New code: ${duplicatedPromo.code}`,
            data: {
                code: duplicatedPromo.code,
                promo: {
                    _id: duplicatedPromo._id,
                    code: duplicatedPromo.code,
                    description: duplicatedPromo.description,
                    rewardType: duplicatedPromo.rewardType,
                    rewardValue: duplicatedPromo.rewardValue,
                    currency: duplicatedPromo.rewardAsset,
                    walletType: duplicatedPromo.walletType || 'main',
                    maxRedemptions: duplicatedPromo.maxUses,
                    targetType: duplicatedPromo.targetType || 'all',
                    targetUserCount: duplicatedPromo.userIds?.length || 0,
                    expiresAt: duplicatedPromo.expiresAt,
                    status: 'draft',
                    category: duplicatedPromo.category || 'deposit',
                    createdAt: duplicatedPromo.createdAt
                }
            }
        });

    } catch (err) {
        console.error('[PROMO DUPLICATE] Error:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to duplicate promo code'
        });
    }
});

app.get('/api/admin/promos/:id/redemptions', adminProtect, restrictTo('super', 'finance'), async (req, res) => {
    try {
        const { id } = req.params;
        const limit = parseInt(req.query.limit) || 20;
        const skip = parseInt(req.query.skip) || 0;

        console.log(`[PROMO REDEMPTIONS] Fetching redemptions for promo: ${id}`);

        if (!mongoose.Types.ObjectId.isValid(id)) {
            return res.status(400).json({
                status: 'fail',
                message: 'Invalid promo ID format'
            });
        }

        const promo = await Promo.findById(id).lean();

        if (!promo) {
            return res.status(404).json({
                status: 'fail',
                message: 'Promo code not found'
            });
        }

        const redemptions = await RedeemedPromo.find({ promoId: promo._id })
            .populate('userId', 'firstName lastName email')
            .sort({ redeemedAt: -1 })
            .skip(skip)
            .limit(limit)
            .lean();

        const totalRedemptions = await RedeemedPromo.countDocuments({ promoId: promo._id });

        const formattedRedemptions = redemptions.map(r => ({
            _id: r._id,
            user: r.userId ? {
                _id: r.userId._id,
                firstName: r.userId.firstName,
                lastName: r.userId.lastName,
                email: r.userId.email
            } : null,
            redeemedAt: r.redeemedAt,
            rewardValue: r.rewardValue,
            rewardAsset: r.rewardAsset || promo.rewardAsset || 'usd',
            transactionId: r.transactionId,
            status: 'completed' // All redemptions are completed by default
        }));

        console.log(`[PROMO REDEMPTIONS] Found ${formattedRedemptions.length} redemptions (total: ${totalRedemptions})`);

        res.status(200).json({
            status: 'success',
            data: {
                redemptions: formattedRedemptions,
                total: totalRedemptions,
                limit: limit,
                skip: skip,
                hasMore: skip + limit < totalRedemptions
            }
        });

    } catch (err) {
        console.error('[PROMO REDEMPTIONS] Error:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to fetch promo redemptions'
        });
    }
});

app.get('/api/admin/promos/export', adminProtect, restrictTo('super', 'finance'), async (req, res) => {
    try {
        const format = req.query.format || 'csv';
        const statusFilter = req.query.status || 'all';

        console.log(`[PROMO EXPORT] Exporting promos in ${format} format`);

        let query = {};
        const now = new Date();

        if (statusFilter !== 'all') {
            if (statusFilter === 'active') {
                query = {
                    isActive: true,
                    expiresAt: { $gt: now },
                    $expr: { $lt: ['$usedCount', '$maxUses'] }
                };
            } else if (statusFilter === 'expired') {
                query = { expiresAt: { $lte: now } };
            } else if (statusFilter === 'exhausted') {
                query = {
                    $expr: { $gte: ['$usedCount', '$maxUses'] }
                };
            } else if (statusFilter === 'paused') {
                query = {
                    isActive: false,
                    expiresAt: { $gt: now },
                    $expr: { $lt: ['$usedCount', '$maxUses'] }
                };
            } else if (statusFilter === 'disabled') {
                query = {
                    isActive: false,
                    $expr: { $gte: ['$usedCount', '$maxUses'] }
                };
            }
        }

        const promos = await Promo.find(query)
            .populate('createdBy', 'name email')
            .sort({ createdAt: -1 })
            .lean();

        const enrichedPromos = await Promise.all(promos.map(async (promo) => {
            const usedCount = await RedeemedPromo.countDocuments({ promoId: promo._id });
            const isExpired = new Date(promo.expiresAt) <= now;
            const isExhausted = usedCount >= promo.maxUses;
            
            let status = 'draft';
            if (promo.isActive && !isExpired && !isExhausted) status = 'active';
            else if (!promo.isActive && !isExpired && !isExhausted) status = 'paused';
            else if (isExpired) status = 'expired';
            else if (isExhausted) status = 'exhausted';
            else if (!promo.isActive) status = 'disabled';

            return {
                ...promo,
                usedCount: usedCount,
                status: status,
                remainingUses: Math.max(0, promo.maxUses - usedCount)
            };
        }));

        if (format === 'json') {
            return res.status(200).json({
                status: 'success',
                data: enrichedPromos
            });
        }

        const headers = [
            'Code',
            'Description',
            'Reward Type',
            'Reward Value',
            'Currency',
            'Target Type',
            'Target Users',
            'Max Uses',
            'Used Count',
            'Remaining Uses',
            'Status',
            'Expires At',
            'Created By',
            'Created At'
        ];

        let csv = headers.join(',') + '\n';

        for (const promo of enrichedPromos) {
            const row = [
                `"${promo.code}"`,
                `"${(promo.description || '').replace(/"/g, '""')}"`,
                `"${promo.rewardType}"`,
                promo.rewardValue,
                `"${promo.rewardAsset || 'usd'}"`,
                `"${promo.targetType || 'all'}"`,
                promo.userIds?.length || 0,
                promo.maxUses,
                promo.usedCount || 0,
                Math.max(0, promo.maxUses - (promo.usedCount || 0)),
                `"${promo.status}"`,
                `"${new Date(promo.expiresAt).toISOString().split('T')[0]}"`,
                `"${promo.createdBy?.name || 'System'}"`,
                `"${new Date(promo.createdAt).toISOString().split('T')[0]}"`
            ];
            csv += row.join(',') + '\n';
        }

        res.setHeader('Content-Type', 'text/csv');
        res.setHeader('Content-Disposition', `attachment; filename=promos-export-${new Date().toISOString().split('T')[0]}.csv`);

        console.log(`[PROMO EXPORT] Exported ${enrichedPromos.length} promos`);

        res.status(200).send(csv);

    } catch (err) {
        console.error('[PROMO EXPORT] Error:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to export promos'
        });
    }
});







const FACIAL_SESSION_TTL = 15 * 60; // 15 minutes
const FACIAL_SESSION_PREFIX = 'kyc:facial:session:';

const createFacialSession = async (userId) => {
    const sessionId = crypto.randomBytes(24).toString('hex');
    const sessionData = {
        sessionId,
        userId: userId.toString(),
        status: 'pending',        // pending | processing | verified | rejected | failed
        reason: null,
        imageKey: null,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };
    await redis.setex(
        `${FACIAL_SESSION_PREFIX}${sessionId}`,
        FACIAL_SESSION_TTL,
        JSON.stringify(sessionData)
    );
    return sessionData;
};

const getFacialSession = async (sessionId) => {
    if (!sessionId) return null;
    const raw = await redis.get(`${FACIAL_SESSION_PREFIX}${sessionId}`);
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return null; }
};

const updateFacialSession = async (sessionId, updates) => {
    const existing = await getFacialSession(sessionId);
    if (!existing) return null;
    const merged = {
        ...existing,
        ...updates,
        updatedAt: new Date().toISOString()
    };
    await redis.setex(
        `${FACIAL_SESSION_PREFIX}${sessionId}`,
        FACIAL_SESSION_TTL,
        JSON.stringify(merged)
    );
    return merged;
};

app.get('/api/users/kyc/status', protect, async (req, res) => {
    try {
        const userId = req.user._id;

        const kycRecord = await KYC.findOne({ user: userId }).lean();

        const mapComponentStatus = (status) => {
            if (!status) return 'incomplete';
            const s = String(status).toLowerCase();
            if (s === 'not-submitted') return 'incomplete';
            return s;
        };

        if (!kycRecord) {
            return res.status(200).json({
                status: 'success',
                data: {
                    application: { status: 'draft' },
                    applicationStatus: 'draft',
                    identity: { status: 'incomplete' },
                    address: { status: 'incomplete' },
                    facial: { status: 'incomplete' },
                    identityStatus: 'incomplete',
                    addressStatus: 'incomplete',
                    facialStatus: 'incomplete',
                    identityComplete: false,
                    addressComplete: false,
                    facialComplete: false,
                    message: 'Your KYC verification has not been started yet.',
                    rejectionReason: null
                }
            });
        }

        const identityStatus = mapComponentStatus(kycRecord.identity?.status);
        const addressStatus = mapComponentStatus(kycRecord.address?.status);
        const facialStatus = mapComponentStatus(kycRecord.facial?.status);

        let applicationStatus = 'draft';
        const overall = (kycRecord.overallStatus || 'not-started').toLowerCase();
        if (overall === 'pending') applicationStatus = 'pending';
        else if (overall === 'verified') applicationStatus = 'verified';
        else if (overall === 'rejected') applicationStatus = 'rejected';
        else if (overall === 'in-progress') applicationStatus = 'draft';
        else applicationStatus = 'draft';

        let rejectionReason = null;
        if (identityStatus === 'rejected') rejectionReason = kycRecord.identity?.rejectionReason || null;
        else if (addressStatus === 'rejected') rejectionReason = kycRecord.address?.rejectionReason || null;
        else if (facialStatus === 'rejected') rejectionReason = kycRecord.facial?.rejectionReason || null;
        if (!rejectionReason) rejectionReason = kycRecord.adminNotes || null;

        let message = 'Your KYC verification is in progress.';
        if (applicationStatus === 'pending') message = 'Your KYC application is under review.';
        else if (applicationStatus === 'verified') message = 'Your identity has been verified.';
        else if (applicationStatus === 'rejected') message = 'Your KYC application was rejected. Please review the feedback and resubmit.';
        else if (identityStatus === 'incomplete' && addressStatus === 'incomplete' && facialStatus === 'incomplete') {
            message = 'Your KYC verification has not been started yet.';
        }

        const identityComplete = ['verified', 'approved'].includes(identityStatus);
        const addressComplete = ['verified', 'approved'].includes(addressStatus);
        const facialComplete = ['verified', 'approved'].includes(facialStatus);

        return res.status(200).json({
            status: 'success',
            data: {
                application: { status: applicationStatus },
                applicationStatus,
                identity: { status: identityStatus },
                address: { status: addressStatus },
                facial: { status: facialStatus },
                identityStatus,
                addressStatus,
                facialStatus,
                identityComplete,
                addressComplete,
                facialComplete,
                message,
                rejectionReason,
                submittedAt: kycRecord.submittedAt || null,
                reviewedAt: kycRecord.reviewedAt || null,
                updatedAt: kycRecord.updatedAt || null
            }
        });

    } catch (err) {
        console.error('Error fetching KYC status:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to fetch KYC status'
        });
    }
});

app.post('/api/users/kyc/send-otp', protect, async (req, res) => {
    try {
        const userId = req.user._id;
        const { email } = req.body || {};

        if (!email || typeof email !== 'string' || !validator.isEmail(email)) {
            return res.status(400).json({
                status: 'fail',
                message: 'A valid email address is required'
            });
        }

        const user = await User.findById(userId).select('firstName lastName email');
        if (!user) {
            return res.status(404).json({
                status: 'fail',
                message: 'User not found'
            });
        }

        if (String(user.email).toLowerCase() !== String(email).toLowerCase()) {
            return res.status(403).json({
                status: 'fail',
                message: 'Email does not match the authenticated user'
            });
        }

        const recentOtp = await OTP.findOne({
            email: user.email,
            type: 'kyc_verification',
            used: false,
            createdAt: { $gte: new Date(Date.now() - 60 * 1000) }
        });

        if (recentOtp) {
            return res.status(429).json({
                status: 'fail',
                message: 'Please wait 60 seconds before requesting a new OTP'
            });
        }

        await OTP.deleteMany({
            email: user.email,
            type: 'kyc_verification',
            used: false
        });

        const otp = Math.floor(100000 + Math.random() * 900000).toString();
        const expiresAt = new Date(Date.now() + 5 * 60 * 1000); // 5 minutes

        await OTP.create({
            email: user.email,
            otp,
            type: 'kyc_verification',
            expiresAt,
            ipAddress: getRealClientIP(req),
            userAgent: req.headers['user-agent'] || 'Unknown'
        });

        await sendProfessionalEmail({
            email: user.email,
            template: 'otp',
            data: {
                name: user.firstName || 'User',
                otp,
                action: 'KYC verification'
            }
        });

        await logActivity(
            'kyc_otp_sent',
            'kyc',
            userId,
            userId,
            'User',
            req,
            { email: user.email, type: 'kyc_verification' }
        );

        return res.status(200).json({
            status: 'success',
            message: 'OTP sent successfully'
        });

    } catch (err) {
        console.error('Send KYC OTP error:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to send OTP'
        });
    }
});

app.post('/api/users/kyc/facial/session', protect, async (req, res) => {
    try {
        const userId = req.user._id;

        const existingKYC = await KYC.findOne({ user: userId }).lean();
        if (existingKYC) {
            const overall = (existingKYC.overallStatus || '').toLowerCase();
            if (overall === 'pending' || overall === 'verified') {
                return res.status(409).json({
                    status: 'fail',
                    message: 'KYC is already submitted or verified. Cannot start a new facial session.'
                });
            }
            if (existingKYC.facial && ['pending', 'verified'].includes(String(existingKYC.facial.status).toLowerCase())) {
                return res.status(409).json({
                    status: 'fail',
                    message: 'Facial verification is already submitted or verified.'
                });
            }
        }

        const session = await createFacialSession(userId);

        await logActivity(
            'kyc_facial_session_created',
            'kyc',
            userId,
            userId,
            'User',
            req,
            { sessionId: session.sessionId }
        );

        return res.status(200).json({
            status: 'success',
            sessionId: session.sessionId,
            data: {
                sessionId: session.sessionId,
                status: 'pending',
                expiresIn: FACIAL_SESSION_TTL
            }
        });

    } catch (err) {
        console.error('Error creating facial session:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to create facial verification session'
        });
    }
});

app.post(
    '/api/users/kyc/facial/submit',
    protect,
    upload.single('image'),
    async (req, res) => {
        let tempFilePath = null;
        try {
            const userId = req.user._id;
            const { sessionId } = req.body || {};

            if (!sessionId) {
                return res.status(400).json({
                    status: 'fail',
                    message: 'sessionId is required'
                });
            }

            if (!req.file) {
                return res.status(400).json({
                    status: 'fail',
                    message: 'Image file is required'
                });
            }

            tempFilePath = req.file.path;

            const session = await getFacialSession(sessionId);
            if (!session) {
                return res.status(400).json({
                    status: 'fail',
                    message: 'Invalid or expired facial session. Please start over.'
                });
            }

            if (session.userId !== userId.toString()) {
                return res.status(403).json({
                    status: 'fail',
                    message: 'Facial session does not belong to this user'
                });
            }

            const allowedImageTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
            if (!allowedImageTypes.includes(req.file.mimetype)) {
                return res.status(400).json({
                    status: 'fail',
                    message: 'Invalid image type. Only JPG, PNG, and WEBP are allowed.'
                });
            }

            const existingKYC = await KYC.findOne({ user: userId }).lean();
            if (existingKYC) {
                const facialStatus = String(existingKYC.facial?.status || '').toLowerCase();
                if (['pending', 'verified'].includes(facialStatus)) {
                    return res.status(409).json({
                        status: 'fail',
                        message: 'Facial verification is already submitted or verified.'
                    });
                }
            }

            const imageKey = `kyc/facial/${userId}_${Date.now()}_facial_${req.file.originalname.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
            const fileContent = await fs.promises.readFile(req.file.path);
            await uploadToR2(fileContent, imageKey, req.file.mimetype);

            await fs.promises.unlink(req.file.path).catch(() => {});
            tempFilePath = null;

            let kycRecord = await KYC.findOne({ user: userId });
            if (!kycRecord) {
                kycRecord = new KYC({ user: userId });
            }

            kycRecord.facial = kycRecord.facial || {};
            kycRecord.facial.verificationPhoto = {
                filename: path.basename(imageKey),
                originalName: req.file.originalname,
                mimeType: req.file.mimetype,
                size: req.file.size,
                path: imageKey,
                uploadedAt: new Date()
            };
            kycRecord.facial.status = 'pending';
            kycRecord.facial.submittedAt = new Date();
            kycRecord.facial.rejectionReason = null;

            if (!kycRecord.overallStatus || kycRecord.overallStatus === 'not-started') {
                kycRecord.overallStatus = 'in-progress';
            }
            kycRecord.updatedAt = new Date();

            await kycRecord.save();

            await User.findByIdAndUpdate(userId, {
                'kycStatus.facial': 'pending',
                kycUpdatedAt: new Date()
            });

            await updateFacialSession(sessionId, {
                status: 'processing',
                imageKey,
                reason: null
            });

            const io = req.app.get('io');
            if (io) {
                io.to(`user_${userId}`).emit('kyc_update', {
                    type: 'facial',
                    status: 'pending',
                    overallStatus: kycRecord.overallStatus,
                    timestamp: Date.now()
                });
            }

            await logActivity(
                'kyc_facial_submitted',
                'kyc',
                kycRecord._id,
                userId,
                'User',
                req,
                { sessionId, imageKey }
            );

            return res.status(200).json({
                status: 'success',
                message: 'Facial verification submitted successfully',
                data: {
                    sessionId,
                    status: 'processing',
                    submittedAt: kycRecord.facial.submittedAt
                }
            });

        } catch (err) {
            console.error('Error submitting facial verification:', err);

            if (tempFilePath) {
                await fs.promises.unlink(tempFilePath).catch(() => {});
            }

            res.status(500).json({
                status: 'error',
                message: err.message || 'Failed to submit facial verification'
            });
        }
    }
);

app.get('/api/users/kyc/facial/status', protect, async (req, res) => {
    try {
        const userId = req.user._id;
        const { sessionId } = req.query || {};

        let status = 'pending';
        let reason = null;

        if (sessionId) {
            const session = await getFacialSession(sessionId);
            if (session && session.userId === userId.toString()) {
                status = session.status;
                reason = session.reason;
            }
        }

        const kycRecord = await KYC.findOne({ user: userId }).lean();
        if (kycRecord && kycRecord.facial) {
            const facialStatus = String(kycRecord.facial.status || '').toLowerCase();
            if (facialStatus === 'verified') {
                status = 'verified';
            } else if (facialStatus === 'rejected') {
                status = 'rejected';
                reason = kycRecord.facial.rejectionReason || reason;
            } else if (facialStatus === 'pending') {
                if (status !== 'processing' && status !== 'verified' && status !== 'rejected' && status !== 'failed') {
                    status = 'pending';
                }
            }
        }

        if (sessionId && (status === 'verified' || status === 'rejected' || status === 'failed')) {
            const session = await getFacialSession(sessionId);
            if (session && session.userId === userId.toString()) {
                let kycRecordMutable = await KYC.findOne({ user: userId });
                if (kycRecordMutable) {
                    if (status === 'verified') {
                        kycRecordMutable.facial.status = 'verified';
                        kycRecordMutable.facial.verifiedAt = kycRecordMutable.facial.verifiedAt || new Date();
                    } else {
                        kycRecordMutable.facial.status = 'rejected';
                        kycRecordMutable.facial.rejectionReason = session.reason || 'Facial verification failed';
                        kycRecordMutable.facial.verifiedAt = kycRecordMutable.facial.verifiedAt || new Date();
                    }
                    await kycRecordMutable.save();
                }
            }
        }

        return res.status(200).json({
            status,
            reason,
            data: {
                status,
                reason,
                sessionId: sessionId || null,
                timestamp: Date.now()
            }
        });

    } catch (err) {
        console.error('Error fetching facial status:', err);
        res.status(500).json({
            status: 'error',
            message: err.message || 'Failed to fetch facial verification status'
        });
    }
});

