const setupMarketWebSocket = (server) => {
  const marketWss = new WebSocket.Server({ 
    server, 
    path: '/ws/market' 
  });

  const clients = new Set();
  let wsPriceInterval = null;

  const broadcastRealPrices = async () => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 8000);
      
      const response = await axios.get(
        'https://api.coingecko.com/api/v3/coins/markets',
        {
          params: {
            vs_currency: 'usd',
            per_page: 100,
            price_change_percentage: '24h',
            sparkline: false
          },
          timeout: 8000,
          signal: controller.signal,
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
          }
        }
      );
      clearTimeout(timeoutId);

      if (response.data && Array.isArray(response.data) && response.data.length > 0 && clients.size > 0) {
        const updates = response.data.map(coin => ({
          assetId: coin.id,
          symbol: coin.symbol.toUpperCase(),
          name: coin.name,
          price: coin.current_price,
          price_change_percentage_24h: coin.price_change_percentage_24h || 0,
          volume_24h: coin.total_volume,
          market_cap: coin.market_cap,
          last_updated: coin.last_updated
        }));

        const message = JSON.stringify({
          type: 'batch_update',
          updates: updates,
          timestamp: Date.now(),
          source: 'coingecko'
        });

        clients.forEach(client => {
          if (client.readyState === WebSocket.OPEN) {
            client.send(message);
          }
        });
        
        console.log(`📡 Broadcasted REAL prices for ${updates.length} assets to ${clients.size} clients`);
      } else if (clients.size > 0) {
        const errorMessage = JSON.stringify({
          type: 'error',
          message: 'Unable to fetch real-time prices. Please refresh.',
          timestamp: Date.now()
        });
        
        clients.forEach(client => {
          if (client.readyState === WebSocket.OPEN) {
            client.send(errorMessage);
          }
        });
      }
    } catch (error) {
      console.error('WebSocket price broadcast error:', error);
      
      const errorMessage = JSON.stringify({
        type: 'error',
        message: error.code === 'ECONNABORTED' ? 'Price service timeout. Please try again.' : 'Unable to fetch real-time prices.',
        timestamp: Date.now()
      });
      
      clients.forEach(client => {
        if (client.readyState === WebSocket.OPEN) {
          client.send(errorMessage);
        }
      });
    }
  };

  marketWss.on('connection', async (ws) => {
    clients.add(ws);
    console.log(`Market WebSocket client connected. Total: ${clients.size}`);

    try {
      const realAssets = await fetchMarketData();
      if (realAssets && realAssets.length > 0) {
        ws.send(JSON.stringify({
          type: 'initial_data',
          assets: realAssets,
          source: 'coingecko',
          timestamp: Date.now()
        }));
      } else {
        ws.send(JSON.stringify({
          type: 'error',
          message: 'Unable to fetch initial market data. Please refresh.',
          timestamp: Date.now()
        }));
      }
    } catch (err) {
      ws.send(JSON.stringify({
        type: 'error',
        message: 'Unable to fetch initial market data',
        timestamp: Date.now()
      }));
    }

    if (clients.size === 1 && !wsPriceInterval) {
      wsPriceInterval = setInterval(broadcastRealPrices, 10000);
      console.log('⏲️ Started real price broadcast interval');
    }

    ws.on('close', () => {
      clients.delete(ws);
      console.log(`Market WebSocket client disconnected. Total: ${clients.size}`);
      
      if (clients.size === 0 && wsPriceInterval) {
        clearInterval(wsPriceInterval);
        wsPriceInterval = null;
        console.log('⏲️ Stopped price broadcast interval (no clients)');
      }
    });
  });
};

let currentPrices = {};

async function buildRealAssetData(user, userId) {
  const assetData = [];
  const mainHoldings = new Map();
  const maturedHoldings = new Map();
  const priceErrors = [];
  
  if (user.balances && user.balances.main) {
    for (const [asset, balance] of user.balances.main.entries()) {
      if (balance > 0 && asset !== 'usd') {
        mainHoldings.set(asset, balance);
      }
    }
  }
  
  if (user.balances && user.balances.matured) {
    for (const [asset, balance] of user.balances.matured.entries()) {
      if (balance > 0 && asset !== 'usd') {
        maturedHoldings.set(asset, balance);
      }
    }
  }
  
  const allAssets = new Set([...mainHoldings.keys(), ...maturedHoldings.keys()]);
  
  const buyTransactions = await Transaction.find({
    user: userId,
    type: 'buy',
    status: 'completed'
  }).sort({ createdAt: -1 });
  
  for (const asset of allAssets) {
    const mainBalance = mainHoldings.get(asset) || 0;
    const maturedBalance = maturedHoldings.get(asset) || 0;
    const totalBalance = mainBalance + maturedBalance;
    
    if (totalBalance > 0) {
      const price = await getCryptoPrice(asset.toUpperCase());
      
      if (!price || price <= 0) {
        priceErrors.push(asset);
        continue;
      }
      
      const mainValue = mainBalance * price;
      const maturedValue = maturedBalance * price;
      const currentValue = totalBalance * price;
      
      const assetBuys = buyTransactions.filter(tx => {
        const txAsset = (tx.asset || tx.buyDetails?.asset || '').toLowerCase();
        return txAsset === asset;
      });
      
      let totalSpent = 0;
      let totalBought = 0;
      assetBuys.forEach(b => {
        totalSpent += b.amount || b.buyDetails?.amountUSD || 0;
        totalBought += b.assetAmount || b.buyDetails?.assetAmount || 0;
      });
      
      const avgPrice = totalBought > 0 ? totalSpent / totalBought : price;
      const unrealizedPnl = currentValue - totalSpent;
      const unrealizedPercentage = totalSpent > 0 ? (unrealizedPnl / totalSpent) * 100 : 0;
      
      assetData.push({
        symbol: asset,
        balance: totalBalance,
        mainBalance: mainBalance,
        maturedBalance: maturedBalance,
        mainValue: mainValue,
        maturedValue: maturedValue,
        currentValue: currentValue,
        avgPrice: avgPrice,
        totalSpent: totalSpent,
        totalBought: totalBought,
        unrealizedPnl: unrealizedPnl,
        unrealizedPnlPercent: unrealizedPercentage,
        id: asset === 'btc' ? 'bitcoin' : asset === 'eth' ? 'ethereum' : asset,
        currentPrice: price,
        transactions: assetBuys.slice(-10).map(b => ({
          amount: b.assetAmount || b.buyDetails?.assetAmount || 0,
          price: b.buyDetails?.buyingPrice || b.exchangeRateAtTime || 0,
          date: b.createdAt
        }))
      });
    }
  }
  
  return assetData;
}

async function calculateRealWalletBalances(user) {
  let mainUSD = 0;
  let activeUSD = 0;
  let maturedUSD = 0;
  const priceErrors = [];
  const mainBreakdown = [];
  const maturedBreakdown = [];
  
  if (user.balances && user.balances.main) {
    for (const [asset, balance] of user.balances.main.entries()) {
      if (balance > 0 && asset !== 'usd') {
        const price = await getCryptoPrice(asset.toUpperCase());
        if (price && price > 0) {
          const value = balance * price;
          mainUSD += value;
          mainBreakdown.push({ asset, balance, price, value });
        } else {
          priceErrors.push(asset);
        }
      }
    }
  }
  
  if (user.balances && user.balances.active) {
    for (const [asset, balance] of user.balances.active.entries()) {
      if (balance > 0) {
        if (asset === 'usd') {
          activeUSD += balance;
        } else {
          activeUSD += balance;
        }
      }
    }
  }
  
  if (user.balances && user.balances.matured) {
    for (const [asset, balance] of user.balances.matured.entries()) {
      if (balance > 0 && asset !== 'usd') {
        const price = await getCryptoPrice(asset.toUpperCase());
        if (price && price > 0) {
          const value = balance * price;
          maturedUSD += value;
          maturedBreakdown.push({ asset, balance, price, value });
        } else {
          priceErrors.push(asset);
        }
      }
    }
  }
  
  return { mainUSD, activeUSD, maturedUSD, priceErrors, mainBreakdown, maturedBreakdown };
}

io.on('connection', async (socket) => {
  console.log('New client connected:', socket.id);
  
  const userId = socket.userId;
  const sessionId = socket.sessionId;
  const isAuthenticated = socket.isAuthenticated;
  const isAdmin = socket.isAdmin;

  if (userId) {
    socket.join(`user_${userId}`);
    console.log(`Socket authenticated for user: ${userId}, session: ${sessionId}`);
  }

  if (isAuthenticated && userId && !isAdmin) {
    try {
      const user = await User.findById(userId).select('balances');
      if (user) {
        const { mainUSD, activeUSD, maturedUSD, priceErrors, mainBreakdown, maturedBreakdown } = await calculateRealWalletBalances(user);
        
        if (priceErrors.length > 0) {
          socket.emit('error', {
            type: 'price_fetch_failed',
            message: `Unable to fetch current prices for: ${priceErrors.join(', ').toUpperCase()}. Please try again.`,
            missingAssets: priceErrors,
            timestamp: Date.now()
          });
        } else {
          socket.emit('balance_update', {
            main: mainUSD,
            active: activeUSD,
            matured: maturedUSD,
            breakdown: {
              main: mainBreakdown,
              matured: maturedBreakdown
            },
            timestamp: Date.now()
          });
          
          console.log(`💰 Sent REAL balance to user ${userId}: MAIN=$${mainUSD.toFixed(2)}, ACTIVE=$${activeUSD.toFixed(2)}, MATURED=$${maturedUSD.toFixed(2)}`);
          console.log(`   MAIN breakdown: ${mainBreakdown.map(a => `${a.balance} ${a.asset.toUpperCase()}`).join(', ')}`);
          console.log(`   MATURED breakdown: ${maturedBreakdown.map(a => `${a.balance} ${a.asset.toUpperCase()}`).join(', ')}`);
          
          const assetData = await buildRealAssetData(user, userId);
          if (assetData.length > 0) {
            socket.emit('asset_balances_update', assetData);
          }
        }
      }
      
      const userPref = await UserPreference.findOne({ user: userId });
      if (userPref) {
        socket.emit('preferences_update', {
          displayAsset: userPref.displayAsset,
          language: userPref.language,
          currency: userPref.currency
        });
      }
    } catch (err) {
      console.error('Error sending initial data to user:', err);
      socket.emit('error', { type: 'data_error', message: 'Failed to load user data' });
    }
  }

  const currentStats = await getCurrentStats();
  socket.emit('stats-update', currentStats);
  console.log(`📡 Sent stats to client ${socket.id}: ${currentStats.totalInvestors.toLocaleString()} investors`);

  socket.on('forced_logout', (data) => {
    console.log(`🔴 Socket ${socket.id} forced to logout:`, data);
    socket.emit('logout_acknowledged', { 
      timestamp: Date.now(),
      reason: data.reason || 'forced_logout'
    });
    setTimeout(() => {
      socket.disconnect(true);
    }, 100);
  });

  socket.on('authenticate', async (token) => {
    try {
      const decoded = verifyJWT(token);
      if (!decoded.isAdmin) {
        socket.emit('auth_error', { message: 'Admin access required' });
        socket.disconnect();
        return;
      }

      const admin = await Admin.findById(decoded.id);
      if (!admin) {
        socket.emit('auth_error', { message: 'Admin not found' });
        socket.disconnect();
        return;
      }

      socket.adminId = admin._id;
      socket.isAdmin = true;
      console.log(`Admin ${admin.email} connected`);
      socket.emit('auth_success', { role: 'admin', name: admin.name });
    } catch (err) {
      console.error('Admin authentication error:', err);
      socket.emit('auth_error', { message: 'Authentication failed' });
      socket.disconnect();
    }
  });
  
  socket.on('refresh_pnl', async () => {
    if (userId && isAuthenticated) {
      try {
        const user = await User.findById(userId).select('balances');
        let totalMainValue = 0;
        let previousDayValue = 0;
        
        if (user && user.balances && user.balances.main) {
          for (const [asset, balance] of user.balances.main.entries()) {
            if (balance > 0 && asset !== 'usd') {
              const currentPrice = await getCryptoPrice(asset.toUpperCase());
              if (currentPrice && currentPrice > 0) {
                totalMainValue += balance * currentPrice;
                
                let change24h = 0;
                try {
                  const assetUpper = asset.toUpperCase();
                  const priceData = await getCryptoPriceWithChange(assetUpper);
                  change24h = priceData?.change24h || 0;
                } catch (err) {
                  change24h = 0;
                }
                
                const previousPrice = currentPrice / (1 + change24h / 100);
                previousDayValue += balance * previousPrice;
              }
            }
          }
        }
        
        const dailyPnL = totalMainValue - previousDayValue;
        const dailyPnLPercentage = previousDayValue > 0 ? (dailyPnL / previousDayValue) * 100 : 0;
        
        socket.emit('pnl_update', {
          main: {
            amount: dailyPnL,
            percentage: dailyPnLPercentage
          },
          matured: {
            amount: 0,
            percentage: 0
          },
          timestamp: Date.now()
        });
      } catch (err) {
        console.error('Error refreshing PNL:', err);
        socket.emit('error', { type: 'pnl_error', message: 'Failed to refresh PNL' });
      }
    }
  });

  socket.on('subscribe_wallet_balances', async (walletAddress) => {
    if (!walletAddress) {
      socket.emit('wallet_error', { message: 'Wallet address is required' });
      return;
    }

    if (!isAuthenticated || !userId) {
      socket.emit('wallet_error', { message: 'Authentication required' });
      return;
    }

    try {
      const user = await User.findById(userId);
      if (!user || !user.web3Wallet || user.web3Wallet.address.toLowerCase() !== walletAddress.toLowerCase()) {
        socket.emit('wallet_error', { message: 'Unauthorized wallet address' });
        return;
      }
    } catch (err) {
      socket.emit('wallet_error', { message: 'Failed to verify wallet ownership' });
      return;
    }

    socket.join(`wallet_${walletAddress.toLowerCase()}`);
    console.log(`Client subscribed to wallet: ${walletAddress}`);

    const interval = setInterval(async () => {
      try {
        const balances = await fetchWalletBalancesFromBlockchain(walletAddress, '0x1');
        socket.emit('wallet_balance_update', {
          walletAddress: walletAddress,
          balances: balances,
          timestamp: Date.now()
        });
      } catch (err) {
        console.error('Error fetching wallet balances:', err);
        socket.emit('wallet_error', { message: 'Failed to fetch balances' });
      }
    }, 30000);

    const cleanup = () => {
      clearInterval(interval);
      socket.leave(`wallet_${walletAddress.toLowerCase()}`);
    };

    socket.on('disconnect', cleanup);
    socket.on('unsubscribe_wallet', cleanup);
  });

  socket.on('disconnect', (reason) => {
    console.log(`Client disconnected: ${socket.id}, reason: ${reason}`);
    if (userId) {
    }
  });
});

async function getCryptoPriceWithChange(asset) {
  try {
    const assetLower = asset.toLowerCase();
    const response = await axios.get(
      `https://api.coingecko.com/api/v3/simple/price?ids=${assetLower}&vs_currencies=usd&include_24hr_change=true`,
      { timeout: 5000 }
    );
    
    if (response.data && response.data[assetLower]) {
      return {
        price: response.data[assetLower].usd,
        change24h: response.data[assetLower].usd_24h_change || 0
      };
    }
    return { price: null, change24h: 0 };
  } catch (err) {
    console.warn(`Could not fetch 24h change for ${asset}:`, err.message);
    return { price: null, change24h: 0 };
  }
}

let balanceBroadcastInterval = null;

const startRealTimeBalanceBroadcaster = () => {
  if (balanceBroadcastInterval) clearInterval(balanceBroadcastInterval);
  
  balanceBroadcastInterval = setInterval(async () => {
    try {
      const rooms = io.sockets.adapter.rooms;
      const userRooms = [];
      
      for (const [roomName, room] of rooms.entries()) {
        if (roomName.startsWith('user_')) {
          const userId = roomName.replace('user_', '');
          userRooms.push(userId);
        }
      }
      
      if (userRooms.length === 0) return;
      
      for (const userId of userRooms) {
        try {
          const user = await User.findById(userId).select('balances');
          if (!user) continue;
          
          const { mainUSD, activeUSD, maturedUSD, priceErrors, mainBreakdown, maturedBreakdown } = await calculateRealWalletBalances(user);
          
          if (priceErrors.length === 0) {
            io.to(`user_${userId}`).emit('balance_update', {
              main: mainUSD,
              active: activeUSD,
              matured: maturedUSD,
              breakdown: {
                main: mainBreakdown,
                matured: maturedBreakdown
              },
              timestamp: Date.now()
            });
            
            const assetData = await buildRealAssetData(user, userId);
            if (assetData.length > 0) {
              io.to(`user_${userId}`).emit('asset_balances_update', assetData);
            }
          }
        } catch (userErr) {
          console.error(`Error broadcasting balance for user ${userId}:`, userErr.message);
        }
      }
      
      console.log(`📡 Broadcasted real-time balances to ${userRooms.length} connected users`);
      
    } catch (err) {
      console.error('Error in balance broadcaster:', err);
    }
  }, 10000);
};

let priceBroadcastInterval = null;

const startRealTimePriceBroadcaster = () => {
  if (priceBroadcastInterval) clearInterval(priceBroadcastInterval);
  
  priceBroadcastInterval = setInterval(async () => {
    try {
      const assets = ['BTC', 'ETH', 'USDT', 'BNB', 'SOL', 'USDC', 'XRP', 'DOGE', 'ADA', 'SHIB', 'AVAX', 'DOT', 'TRX', 'LINK', 'MATIC', 'LTC'];
      const priceUpdates = {};
      
      const pricePromises = assets.map(async (asset) => {
        const price = await getCryptoPrice(asset);
        if (price && price > 0) {
          priceUpdates[asset.toLowerCase()] = {
            price: price,
            change24h: 0,
            timestamp: Date.now()
          };
        }
      });
      
      await Promise.all(pricePromises);
      
      if (Object.keys(priceUpdates).length > 0) {
        io.emit('price_update', priceUpdates);
        console.log(`📊 Broadcasted real-time price updates for ${Object.keys(priceUpdates).length} assets`);
        
        for (const [asset, data] of Object.entries(priceUpdates)) {
          if (!currentPrices[asset]) currentPrices[asset] = {};
          currentPrices[asset].usd = data.price;
        }
      }
    } catch (err) {
      console.error('Error in price broadcaster:', err);
    }
  }, 5000);
};

const processMaturedInvestments = async () => {
  try {
    const now = new Date();
    const maturedInvestments = await Investment.find({
      status: 'active',
      endDate: { $lte: now }
    }).populate('user plan');

    if (maturedInvestments.length === 0) {
      return;
    }

    console.log(`🔄 Processing ${maturedInvestments.length} matured investments...`);

    for (const investment of maturedInvestments) {
      try {
        const user = await User.findById(investment.user._id);
        if (!user) {
          console.error(`User not found for investment ${investment._id}`);
          continue;
        }

        if (!investment.amount || investment.amount <= 0) {
          console.error(`Investment ${investment._id} has invalid amount: ${investment.amount}`);
          continue;
        }

        if (!investment.plan || !investment.plan.percentage) {
          console.error(`Investment ${investment._id} has invalid plan percentage`);
          continue;
        }

        const totalReturn = investment.amount + (investment.amount * investment.plan.percentage / 100);
        
        if (!user.balances) {
          user.balances = { main: new Map(), active: new Map(), matured: new Map() };
        }
        if (!user.balances.active) user.balances.active = new Map();
        if (!user.balances.matured) user.balances.matured = new Map();
        
        const currentActiveUSD = user.balances.active.get('usd') || 0;
        const currentMaturedUSD = user.balances.matured.get('usd') || 0;
        
        if (currentActiveUSD < investment.amount) {
          console.error(`Insufficient active balance for user ${user._id}. Required: ${investment.amount}, Available: ${currentActiveUSD}`);
          continue;
        }
        
        const newActiveUSD = currentActiveUSD - investment.amount;
        const newMaturedUSD = currentMaturedUSD + totalReturn;
        
        if (newActiveUSD <= 0.01) {
          user.balances.active.delete('usd');
        } else {
          user.balances.active.set('usd', newActiveUSD);
        }
        
        user.balances.matured.set('usd', newMaturedUSD);
        
        user.markModified('balances.active');
        user.markModified('balances.matured');
        
        investment.status = 'completed';
        investment.completionDate = now;
        investment.actualReturn = totalReturn - investment.amount;

        await user.save();
        await investment.save();

        await Transaction.create({
          user: investment.user._id,
          type: 'interest',
          amount: totalReturn - investment.amount,
          currency: 'USD',
          status: 'completed',
          method: 'internal',
          reference: `AUTO-RET-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          details: {
            investmentId: investment._id,
            planName: investment.plan.name,
            principal: investment.amount,
            interest: totalReturn - investment.amount,
            totalReturn: totalReturn
          },
          fee: 0,
          netAmount: totalReturn - investment.amount
        });
        
        const { mainUSD, activeUSD, maturedUSD, mainBreakdown, maturedBreakdown } = await calculateRealWalletBalances(user);
        
        io.to(`user_${user._id}`).emit('balance_update', {
          main: mainUSD,
          active: activeUSD,
          matured: maturedUSD,
          breakdown: {
            main: mainBreakdown,
            matured: maturedBreakdown
          },
          timestamp: Date.now()
        });

        console.log(`✅ Completed investment ${investment._id} for ${user.email}: $${investment.amount} → $${totalReturn.toFixed(2)}`);
        
      } catch (err) {
        console.error(`Error processing investment ${investment._id}:`, err);
      }
    }
  } catch (err) {
    console.error('Error processing matured investments:', err);
  }
};


setInterval(processMaturedInvestments, 60 * 1000);
processMaturedInvestments();

startInvestorGrowthJob();

startRealTimeBalanceBroadcaster();

startRealTimePriceBroadcaster();

startPnLCronJob(io);

const gracefulShutdown = () => {
  console.log('Received shutdown signal. Cleaning up...');
  
  if (priceBroadcastInterval) clearInterval(priceBroadcastInterval);
  if (balanceBroadcastInterval) clearInterval(balanceBroadcastInterval);
  stopInvestorGrowthJob();
  
  io.close(() => {
    console.log('Socket.IO server closed');
    process.exit(0);
  });
  
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

